// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🛠️rendergoaltreenodes](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/d/i/renderGoalTreeNodes)
// renderGoalTreeNodes holds the data fields for a renderGoalTreeNodes record.
// renderGoalTreeNodes MUST perform the renderGoalTreeNodes operation.
func renderGoalTreeNodes(roots []*GoalNode, format string) string {
	var sb strings.Builder

	var render func(node interface{}, prefix string, isLast bool, isRoot bool)
	render = func(node interface{}, prefix string, isLast bool, isRoot bool) {
		var lineContent string
		var children []interface{}

		switch n := node.(type) {
		case *GoalNode:
			data := goalNodeToData(n)
			if format == "md" {
				lineContent = renderEntityMarkdownLink("goal", data)
			} else {
				lineContent = renderEntityHuman("goal", data, false)
			}
			for _, c := range n.Children {
				children = append(children, c)
			}
			for _, t := range n.Tickets {
				children = append(children, t)
			}
		case *TicketNode:
			data := ticketNodeToData(n)
			if format == "md" {
				lineContent = renderEntityMarkdownLink("ticket", data)
			} else {
				lineContent = renderEntityHuman("ticket", data, false)
			}
			for _, c := range n.Children {
				children = append(children, c)
			}
		}

		if format == "text" {
			connector := ""
			if !isRoot {
				if isLast {
					connector = "└── "
				} else {
					connector = "├── "
				}
			}
			sb.WriteString(prefix + connector + lineContent + "\n")

			newPrefix := prefix
			if !isRoot {
				if isLast {
					newPrefix += "    "
				} else {
					newPrefix += "│   "
				}
			}

			for i, child := range children {
				render(child, newPrefix, i == len(children)-1, false)
			}
		} else {

			sb.WriteString(prefix + "- " + lineContent + "\n")
			newPrefix := prefix + "  "
			for i, child := range children {
				render(child, newPrefix, i == len(children)-1, false)
			}
		}
	}

	for i, root := range roots {
		render(root, "", i == len(roots)-1, true)
	}
	return sb.String()
}

// renderSectionTree MUST perform the renderSectionTree operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🪨rendersectiontree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/d/i/renderSectionTree)
// renderSectionTree performs the renderSectionTree operation.
func renderSectionTree(root *Section, isTTY bool, useMD bool) string {
	var sb strings.Builder

	var render func(s *Section, prefix string, isLast bool, isRoot bool)
	render = func(s *Section, prefix string, isLast bool, isRoot bool) {
		data := map[string]interface{}{
			"path":      s.Path,
			"name":      s.Name,
			"startLine": float64(s.StartLine),
			"endLine":   float64(s.EndLine),
		}

		var lineContent string
		if useMD {
			lineContent = renderEntityMarkdown("section", data)
		} else {
			lineContent = renderEntityHuman("section", data, false)
		}

		if !useMD {
			connector := ""
			if !isRoot {
				if isLast {
					connector = "└── "
				} else {
					connector = "├── "
				}
			}
			sb.WriteString(prefix + connector + lineContent + "\n")
			newPrefix := prefix
			if !isRoot {
				if isLast {
					newPrefix += "    "
				} else {
					newPrefix += "│   "
				}
			}
			for i := range s.Children {
				childPtr := &s.Children[i]
				render(childPtr, newPrefix, i == len(s.Children)-1, false)
			}
		} else {
			sb.WriteString(prefix + lineContent + "\n")
			newPrefix := prefix + "  "
			for i := range s.Children {
				childPtr := &s.Children[i]
				render(childPtr, newPrefix, i == len(s.Children)-1, false)
			}
		}
	}

	render(root, "", true, true)
	return sb.String()
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🛠️renderticketlist](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/d/i/renderTicketList)
