// #region 🔖Monorepo Tree

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree)
// Monorepo tree builder that assembles all entity nodes into a unified tree.

// TreeBuildOptions holds the data fields for a tree build options record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree✂️treebuildoptions](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/TreeBuildOptions)
type TreeBuildOptions struct {
	IncludeSections bool
}

// BuildMonorepoTree MUST assemble the monorepo tree from the available context data.
// BuildMonorepoTree constructs and returns the monorepo tree structure.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️buildmonorepotree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/BuildMonorepoTree)
func BuildMonorepoTree(ctx context.Context, opts ...TreeBuildOptions) *TreeNode {
	var options TreeBuildOptions
	if len(opts) > 0 {
		options = opts[0]
	}
	root := &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}

	var technologies []Technology
	var goals []*Goal
	var drafts []*Draft
	var policies []PolicyDef
	var contributors []Contributor
	var checkpoints []Checkpoint
	var allFolders []Folder
	var allFiles []File
	var sessions []Session

	var wg sync.WaitGroup
	wg.Add(9)

	go func() {
		defer wg.Done()
		technologies = LoadTechnologies()
	}()
	go func() {
		defer wg.Done()
		goalCh := make(chan *Goal)
		go func() { StreamGoals(ctx, goalCh) }()
		for g := range goalCh {
			goals = append(goals, g)
		}
	}()
	go func() {
		defer wg.Done()
		drafts, _ = ListDrafts()
	}()
	go func() {
		defer wg.Done()
		policyCh := make(chan PolicyDef)
		go func() { StreamPolicies(ctx, policyCh) }()
		for p := range policyCh {
			policies = append(policies, p)
		}
	}()
	go func() {
		defer wg.Done()
		contribCh := make(chan Contributor)
		go func() { StreamContributors(ctx, contribCh) }()
		for c := range contribCh {
			contributors = append(contributors, c)
		}
	}()
	go func() {
		defer wg.Done()
		limit := 100
		checkpoints = LoadCheckpoints(&limit)
	}()
	go func() {
		defer wg.Done()
		folderCh := make(chan Folder)
		go func() { StreamFolders(ctx, "", folderCh) }()
		for f := range folderCh {
			allFolders = append(allFolders, f)
		}
	}()
	go func() {
		defer wg.Done()
		fileCh := make(chan File)
		go func() { StreamFiles(ctx, "", fileCh) }()
		for f := range fileCh {
			allFiles = append(allFiles, f)
		}
	}()
	go func() {
		defer wg.Done()
		sessionCh := make(chan Session)
		go func() { StreamSessions(ctx, sessionCh) }()
		for s := range sessionCh {
			sessions = append(sessions, s)
		}
	}()
	wg.Wait()

	codebaseNode := &TreeNode{Kind: TreeNodeCategory, ID: "codebase", Label: "�️Codebase", URI: "repo://codebase"}
	sort.Slice(technologies, func(i, j int) bool { return technologies[i].Name < technologies[j].Name })

	type folderEntry struct {
		folder *Folder
		node   *TreeNode
	}
	globalFolderMap := make(map[string]*folderEntry)
	for fi := range allFolders {
		f := &allFolders[fi]
		fNode := &TreeNode{
			Kind:    TreeNodeFolder,
			ID:      f.GetID(),
			Label:   f.Name,
			URI:     f.GetURI(),
			SubKind: string(f.Kind),
			Data:    map[string]interface{}{"path": f.Path, "name": f.Name, "kind": string(f.Kind)},
		}
		globalFolderMap[f.Path] = &folderEntry{folder: f, node: fNode}
	}

	globalFileNodes := make(map[string]*TreeNode)
	for fi := range allFiles {
		f := &allFiles[fi]
		fileNode := &TreeNode{
			Kind:    TreeNodeFile,
			ID:      f.GetID(),
			Label:   f.Name,
			URI:     f.GetURI(),
			SubKind: f.Kind,
			Data:    map[string]interface{}{"path": f.Path, "name": f.Name, "kind": f.Kind},
		}
		if options.IncludeSections {
			absPath := filepath.Join(GetRootDir(), f.Path)
			content, err := ReadTextFile(absPath)
			if err == nil {
				sections := ParseSections(content, f.Path)
				definitions := ParseDefinitions(content, f.Path)
				sections = HydrateSectionsWithDefinitions(sections, definitions)
				for si := range sections {
					s := &sections[si]
					sNode := buildSectionTreeNode(s)
					fileNode.Children = append(fileNode.Children, sNode)
				}
			}
		}
		globalFileNodes[f.Path] = fileNode
	}

	folderRoots := buildFolderRoots(allFolders)
	for _, folderRoot := range folderRoots {
		codebaseNode.Children = append(codebaseNode.Children, folderRoot)
	}
	attachFilesToFolders(codebaseNode, allFiles, globalFileNodes)

	for pi := range technologies {
		p := &technologies[pi]
		pNode := &TreeNode{
			Kind:    TreeNodeTechnology,
			ID:      p.GetID(),
			Label:   p.Name,
			URI:     p.GetURI(),
			SubKind: string(p.Kind),
			Data:    map[string]interface{}{"name": p.Name, "kind": string(p.Kind)},
		}
		sort.Slice(p.Bundles, func(i, j int) bool { return p.Bundles[i].Name < p.Bundles[j].Name })
		for bi := range p.Bundles {
			b := &p.Bundles[bi]
			bNode := &TreeNode{
				Kind:    TreeNodeBundle,
				ID:      b.GetID(),
				Label:   b.Name,
				URI:     b.GetURI(),
				SubKind: string(b.Kind),
				Data:    map[string]interface{}{"name": b.Name, "root": b.Root, "kind": string(b.Kind)},
			}

			bundleRoot := b.Root
			if b.SourceRoot != "" {
				bundleRoot = b.SourceRoot
			}

			bundleFolderMap := make(map[string]*folderEntry)
			for path, fe := range globalFolderMap {
				if path == bundleRoot || strings.HasPrefix(path, bundleRoot+"/") {
					bundleFolderMap[path] = fe
				}
			}

			for path, fe := range bundleFolderMap {
				parentPath := filepath.Dir(path)
				if _, ok := bundleFolderMap[parentPath]; ok {
					continue
				}
				bNode.Children = append(bNode.Children, fe.node)
			}
			for path, fe := range bundleFolderMap {
				parentPath := filepath.Dir(path)
				if pfe, ok := bundleFolderMap[parentPath]; ok {
					pfe.node.Children = append(pfe.node.Children, fe.node)
				}
			}

			for path, fileNode := range globalFileNodes {
				if path != bundleRoot && !strings.HasPrefix(path, bundleRoot+"/") {
					continue
				}
				folderPath := filepath.Dir(path)
				if fe, ok := bundleFolderMap[folderPath]; ok {
					fe.node.Children = append(fe.node.Children, fileNode)
				} else {
					bNode.Children = append(bNode.Children, fileNode)
				}
			}

			sortTreeChildren(bNode)
			pNode.Children = append(pNode.Children, bNode)
		}
		codebaseNode.Children = append(codebaseNode.Children, pNode)
	}
	sortTreeChildren(codebaseNode)
	root.Children = append(root.Children, codebaseNode)

	goalsNode := &TreeNode{Kind: TreeNodeCategory, ID: "goals", Label: "🎯Goals", URI: "repo://goals"}
	goalMap := make(map[string]*TreeNode)
	sort.Slice(goals, func(i, j int) bool { return goals[i].ID < goals[j].ID })
	for _, g := range goals {
		goalCreatedAt := ""
		gNode := &TreeNode{
			Kind:        TreeNodeGoal,
			ID:          g.GetID(),
			Label:       g.Title,
			URI:         g.GetURI(),
			SubKind:     g.Status,
			Description: g.Description,
			Status:      g.Status,
			Data: map[string]interface{}{
				"id":          g.ID,
				"title":       g.Title,
				"status":      g.Status,
				"dueDate":     g.DueDate,
				"createdAt":   goalCreatedAt,
				"description": g.Description,
			},
		}
		goalMap[g.ID] = gNode
	}
	var rootGoals []*TreeNode
	for _, g := range goals {
		gNode := goalMap[g.ID]
		parentID := ""
		if idx := strings.LastIndex(g.ID, "/"); idx >= 0 {
			parentID = g.ID[:idx]
		}
		if parentID != "" && parentID != g.ID {
			if parent, ok := goalMap[parentID]; ok {
				parent.Children = append(parent.Children, gNode)
			} else {
				rootGoals = append(rootGoals, gNode)
			}
		} else {
			rootGoals = append(rootGoals, gNode)
		}
	}
	goalsNode.Children = rootGoals

	ticketCh := make(chan Ticket)
	go func() { StreamTickets(ctx, nil, nil, nil, ticketCh) }()
	var tickets []Ticket
	for t := range ticketCh {
		tickets = append(tickets, t)
	}
	for ti := range tickets {
		t := &tickets[ti]
		ticketStarted := t.GetDateStarted().Format(time.RFC3339)
		ticketFinished := ""
		if finished := t.GetDateFinished(); finished != nil {
			ticketFinished = finished.Format(time.RFC3339)
		}
		tNode := &TreeNode{
			Kind:        TreeNodeTicket,
			ID:          t.GetID(),
			Label:       t.Title,
			URI:         t.GetURI(),
			Description: t.Description,
			Year:        t.Year,
			Month:       t.Month,
			Day:         t.Day,
			Status:      string(t.Status),
			Data: map[string]interface{}{
				"year":     float64(t.Year),
				"month":    float64(t.Month),
				"day":      float64(t.Day),
				"slug":     t.Slug,
				"title":    t.Title,
				"status":   string(t.Status),
				"started":  ticketStarted,
				"finished": ticketFinished,
				"prompt":   t.Description,
				"summary":  t.Summary,
				"goalId":   t.Goal,
			},
		}
		if t.Goal != "" {
			if gNode, ok := goalMap[t.Goal]; ok {
				gNode.Children = append(gNode.Children, tNode)
				continue
			}
		}
		goalsNode.Children = append(goalsNode.Children, tNode)
	}
	root.Children = append(root.Children, goalsNode)

	draftsNode := &TreeNode{Kind: TreeNodeCategory, ID: "drafts", Label: "✍Drafts", URI: "repo://drafts"}
	if drafts != nil {
		for _, d := range drafts {
			dNode := &TreeNode{
				Kind:  TreeNodeDraft,
				ID:    d.GetID(),
				Label: d.ID,
				URI:   d.GetURI(),
				Data:  map[string]interface{}{"id": d.ID, "slug": d.ID},
			}
			draftsNode.Children = append(draftsNode.Children, dNode)
		}
	}
	root.Children = append(root.Children, draftsNode)

	policiesNode := &TreeNode{Kind: TreeNodeCategory, ID: "policies", Label: "🛡️️Policies", URI: "repo://policies"}
	sort.Slice(policies, func(i, j int) bool { return policies[i].ID < policies[j].ID })
	for _, p := range policies {
		policyId := emojiText(EmojiPolicy) + Flat(strings.TrimPrefix(p.ID, "/"))
		pNode := &TreeNode{
			Kind:        TreeNodePolicy,
			ID:          fmt.Sprintf("%s/%s", emojiText(EmojiPolicy), p.ID),
			Label:       p.Name,
			URI:         "repo://policy/" + policyId,
			Description: p.Description,
			Data:        map[string]interface{}{"id": p.ID, "name": p.Name, "description": p.Description},
		}
		pNode.Children = buildPolicyEntityKindTree(p.Groups)
		policiesNode.Children = append(policiesNode.Children, pNode)
	}
	root.Children = append(root.Children, policiesNode)

	contributorsNode := &TreeNode{Kind: TreeNodeCategory, ID: "contributors", Label: "🧑‍💻Contributors", URI: "repo://contributors"}
	sort.Slice(contributors, func(i, j int) bool { return contributors[i].Alias < contributors[j].Alias })
	for _, c := range contributors {
		label := c.Alias
		if c.Name != "" {
			label = c.Name + " (" + c.Alias + ")"
		}
		contributorData := map[string]interface{}{
			"alias":   c.Alias,
			"aliases": c.Aliases,
			"github":  c.Github,
			"githubs": c.Githubs,
			"name":    c.Name,
			"names":   c.Names,
			"email":   c.Email,
			"emails":  c.Emails,
		}
		cNode := &TreeNode{
			Kind:        TreeNodeContributor,
			ID:          c.GetID(),
			Label:       label,
			URI:         c.GetURI(),
			Contributor: c.Alias,
			Data:        contributorData,
		}
		contributorsNode.Children = append(contributorsNode.Children, cNode)
	}
	root.Children = append(root.Children, contributorsNode)

	checkpointsNode := &TreeNode{Kind: TreeNodeCategory, ID: "checkpoints", Label: "🔀Checkpoints", URI: "repo://checkpoints"}
	for ci := range checkpoints {
		c := &checkpoints[ci]
		cNode := &TreeNode{
			Kind:  TreeNodeCheckpoint,
			ID:    c.GetID(),
			Label: c.SHA[:8] + " " + c.Title,
			URI:   c.GetURI(),
			Year:  c.Date.Year(),
			Month: int(c.Date.Month()),
			Day:   c.Date.Day(),
			Data: map[string]interface{}{"sha": c.SHA, "message": c.Title, "authorId": func() string {
				if c.AuthorID != nil {
					return *c.AuthorID
				}
				return ""
			}()},
		}
		checkpointsNode.Children = append(checkpointsNode.Children, cNode)
	}
	root.Children = append(root.Children, checkpointsNode)

	sessionsNode := &TreeNode{Kind: TreeNodeCategory, ID: "sessions", Label: "⚪Sessions", URI: "repo://sessions"}
	sort.Slice(sessions, func(i, j int) bool { return sessions[i].StartedAt > sessions[j].StartedAt })
	for si := range sessions {
		s := &sessions[si]
		kindEmoji := SessionKindEmoji(s.Kind)
		label := kindEmoji + " " + s.UUID
		if s.Client != "" {
			label += " (" + s.Client + ")"
		}
		sNode := &TreeNode{
			Kind:    TreeNodeSession,
			ID:      s.GetID(),
			Label:   label,
			URI:     s.GetURI(),
			SubKind: string(s.Kind),
			Year:    s.Year,
			Month:   s.Month,
			Day:     s.Day,
			Status:  string(s.Kind),
			Data: map[string]interface{}{
				"uuid":       s.UUID,
				"kind":       string(s.Kind),
				"client":     s.Client,
				"startedAt":  s.StartedAt,
				"year":       float64(s.Year),
				"month":      float64(s.Month),
				"day":        float64(s.Day),
				"checkpoint": s.Checkpoint,
			},
		}
		sessionsNode.Children = append(sessionsNode.Children, sNode)
	}
	root.Children = append(root.Children, sessionsNode)

	PropagateParentIDs(root, "")
	return root
}

// PropagateParentIDs holds the data fields for a PropagateParentIDs record.
// PropagateParentIDs MUST perform the PropagateParentIDs operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️propagateparentids](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/PropagateParentIDs)
func PropagateParentIDs(node *TreeNode, parentArtifactID string) {
	if node.Data == nil {
		node.Data = map[string]interface{}{}
	}
	entityKind := treeNodeKindToEntityKind(node.Kind)
	currentID := ""
	if entityKind != "" && node.Data != nil {
		node.Data["parentId"] = parentArtifactID
		currentID = GetArtifactID(entityKind, node.Data)
	} else {
		currentID = parentArtifactID
	}
	for _, child := range node.Children {
		PropagateParentIDs(child, currentID)
	}
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️buildsectiontreenode](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/buildSectionTreeNode)
// buildSectionTreeNode holds the data fields for a buildSectionTreeNode record.
// buildSectionTreeNode MUST perform the buildSectionTreeNode operation.
func buildSectionTreeNode(s *Section) *TreeNode {
	sNode := &TreeNode{
		Kind:  TreeNodeSection,
		ID:    s.GetID(),
		Label: s.Name,
		URI:   s.GetURI(),
		Data:  map[string]interface{}{"path": s.Path, "name": s.Name, "startLine": float64(s.StartLine), "endLine": float64(s.EndLine)},
	}
	for di := range s.Definitions {
		d := &s.Definitions[di]
		dNode := &TreeNode{
			Kind:    TreeNodeDefinition,
			ID:      d.GetID(),
			Label:   d.Name,
			URI:     d.GetURI(),
			SubKind: string(d.Kind),
			Data:    map[string]interface{}{"path": d.FilePath, "name": d.Name, "kind": string(d.Kind), "startLine": float64(d.StartLine), "endLine": float64(d.EndLine)},
		}
		sNode.Children = append(sNode.Children, dNode)
	}
	for ci := range s.Children {
		child := &s.Children[ci]
		sNode.Children = append(sNode.Children, buildSectionTreeNode(child))
	}
	return sNode
}

// buildStatuteTree holds the data fields for a buildStatuteTree record.
// buildStatuteTree MUST perform the buildStatuteTree operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree✂️buildstatutetree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/buildStatuteTree)
func buildStatuteTree(kinds []Statute) []*TreeNode {
	type treeEntry struct {
		node     *TreeNode
		children map[string]*treeEntry
	}
	rootEntries := make(map[string]*treeEntry)
	orderedRootKeys := []string{}

	for _, k := range kinds {
		parts := strings.Split(string(k), "/")
		current := rootEntries
		currentOrdered := &orderedRootKeys
		for i, part := range parts {
			if _, ok := current[part]; !ok {
				isLeaf := i == len(parts)-1
				meta := k.Info()
				n := &TreeNode{
					Kind:  TreeNodeStatute,
					ID:    string(k),
					Label: part,
					URI:   meta.GetURI(),
				}
				if isLeaf {
					n.Description = meta.Reason
					priorityIcon := "🟢"
					if meta.Priority == BreachPriorityHigh {
						priorityIcon = "🔴"
					} else if meta.Priority == BreachPriorityMedium {
						priorityIcon = "🟡"
					}
					n.Label = priorityIcon + part
					if meta.Autofixable {
						n.SubKind = "autofixable"
					}
					n.Data = map[string]interface{}{
						"id":          string(k),
						"priority":    string(meta.Priority),
						"autofixable": meta.Autofixable,
						"reason":      meta.Reason,
						"solution":    meta.Solution,
					}
				} else {
					prefix := strings.Join(parts[:i+1], "/")
					n.ID = "breachCategory:" + prefix
					n.URI = "repo://statute/" + Flat(prefix)
					n.Kind = TreeNodeCategory
				}
				current[part] = &treeEntry{node: n, children: make(map[string]*treeEntry)}
				*currentOrdered = append(*currentOrdered, part)
			}
			entry := current[part]
			current = entry.children
			childKeys := []string{}
			for ck := range entry.children {
				childKeys = append(childKeys, ck)
			}
			currentOrdered = &childKeys
		}
	}

	var buildNodes func(entries map[string]*treeEntry, keys []string) []*TreeNode
	buildNodes = func(entries map[string]*treeEntry, keys []string) []*TreeNode {
		seen := map[string]bool{}
		var result []*TreeNode
		for _, key := range keys {
			if seen[key] {
				continue
			}
			seen[key] = true
			entry := entries[key]
			childKeys := []string{}
			for ck := range entry.children {
				childKeys = append(childKeys, ck)
			}
			sort.Strings(childKeys)
			entry.node.Children = buildNodes(entry.children, childKeys)
			result = append(result, entry.node)
		}
		return result
	}

	return buildNodes(rootEntries, orderedRootKeys)
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️buildterritorytree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/buildTerritoryTree)
// buildTerritoryTree holds the data fields for a buildTerritoryTree record.
// buildTerritoryTree MUST perform the buildTerritoryTree operation.
func buildTerritoryTree(groups []Territory) []*TreeNode {
	var result []*TreeNode
	for _, g := range groups {
		groupNode := &TreeNode{
			Kind:        TreeNodeCategory,
			ID:          fmt.Sprintf("%s%s", emojiText(EmojiTerritory), g.Name),
			Label:       g.Name,
			URI:         "repo://territory/" + g.GetID(),
			Description: g.Description,
			SubKind:     "territory",
			Data: map[string]interface{}{
				"name":        g.Name,
				"description": g.Description,
				"scopes":      g.Scopes,
			},
		}
		for _, k := range g.Kinds {
			meta := k.Info()
			priorityIcon := "🟢"
			if meta.Priority == BreachPriorityHigh {
				priorityIcon = "🔴"
			} else if meta.Priority == BreachPriorityMedium {
				priorityIcon = "🟡"
			}
			label := priorityIcon + StatutePathToIdValue(string(k))
			vkNode := &TreeNode{
				Kind:        TreeNodeStatute,
				ID:          meta.GetID(),
				Label:       label,
				URI:         meta.GetURI(),
				Description: meta.Reason,
				Data: map[string]interface{}{
					"id":          string(k),
					"priority":    string(meta.Priority),
					"autofixable": meta.Autofixable,
					"reason":      meta.Reason,
					"solution":    meta.Solution,
				},
			}
			if meta.Autofixable {
				vkNode.SubKind = "autofixable"
			}
			groupNode.Children = append(groupNode.Children, vkNode)
		}
		groupNode.Children = append(groupNode.Children, buildTerritoryTree(g.Groups)...)
		result = append(result, groupNode)
	}
	return result
}

// sortTreeChildren MUST perform the sortTreeChildren operation.
// sortTreeChildren holds the data fields for a sortTreeChildren record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️sorttreechildren](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/sortTreeChildren)
func sortTreeChildren(node *TreeNode) {
	sort.Slice(node.Children, func(i, j int) bool {
		a, b := node.Children[i], node.Children[j]
		if a.Kind != b.Kind {
			aIsFolder := a.Kind == TreeNodeFolder
			bIsFolder := b.Kind == TreeNodeFolder
			if aIsFolder != bIsFolder {
				return aIsFolder
			}
		}
		return a.Label < b.Label
	})
	for _, c := range node.Children {
		sortTreeChildren(c)
	}
}

// FilterMonorepoTree MUST preserve the tree structure while removing non-matching nodes.
// FilterMonorepoTree filters the monorepo tree based on the given criteria.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️filtermonorepotree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/FilterMonorepoTree)
func FilterMonorepoTree(root *TreeNode, filter *TreeFilter) *TreeNode {
	if filter == nil {
		return root
	}

	filtered := filterNode(root, filter)
	if filtered == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}

	if filter.HasOnlyKinds() || len(filter.ExcludeKinds) > 0 {
		collapseFilteredKinds(filtered, filter)
	}

	return filtered
}

// filterNode MUST perform the filterNode operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️filternode](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/filterNode)
// filterNode performs the filterNode operation.
func filterNode(node *TreeNode, filter *TreeFilter) *TreeNode {
	if node.Kind != TreeNodeCategory {
		if !filter.IsKindVisible(node.Kind) {
			var kept []*TreeNode
			for _, c := range node.Children {
				fc := filterNode(c, filter)
				if fc != nil {
					kept = append(kept, fc)
				}
			}
			if len(kept) > 0 {
				copy := *node
				copy.Children = kept
				return &copy
			}
			return nil
		}
		if !filter.MatchesSubKind(node.Kind, node.SubKind) {
			return nil
		}
		if node.Year > 0 && !filter.MatchesDate(node.Year, node.Month, node.Day) {
			return nil
		}
		if node.Status != "" && !filter.MatchesStatus(node.Status) {
			return nil
		}
		if node.Contributor != "" && !filter.MatchesContributor(node.Contributor) {
			return nil
		}
	}

	var kept []*TreeNode
	for _, c := range node.Children {
		fc := filterNode(c, filter)
		if fc != nil {
			kept = append(kept, fc)
		}
	}

	if node.Kind == TreeNodeCategory && len(kept) == 0 {
		return nil
	}

	copy := *node
	copy.Children = kept
	return &copy
}

// collapseFilteredKinds MUST perform the collapseFilteredKinds operation.
// collapseFilteredKinds holds the data fields for a collapseFilteredKinds record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🪨collapsefilteredkinds](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/collapseFilteredKinds)
func collapseFilteredKinds(node *TreeNode, filter *TreeFilter) {
	var newChildren []*TreeNode
	for _, c := range node.Children {
		if c.Kind != TreeNodeCategory && !filter.IsKindVisible(c.Kind) {
			collapseFilteredKinds(c, filter)
			newChildren = append(newChildren, c.Children...)
		} else {
			collapseFilteredKinds(c, filter)
			newChildren = append(newChildren, c)
		}
	}
	node.Children = newChildren
}

// searchMonorepoTreeWithCache MUST perform the searchMonorepoTreeWithCache operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️searchmonorepotreewithcache](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/searchMonorepoTreeWithCache)
// searchMonorepoTreeWithCache performs the searchMonorepoTreeWithCache operation.
func searchMonorepoTreeWithCache(ctx context.Context, root *TreeNode, query string) *TreeNode {
	if query == "" {
		return root
	}
	return searchTreeInMemory(root, query)
}

// SearchMonorepoTree MUST match case-insensitively against node labels and descriptions.
// SearchMonorepoTree performs a text search across the monorepo tree.
func SearchMonorepoTree(root *TreeNode, query string) *TreeNode {
	if query == "" {
		return root
	}
	return searchTreeInMemory(root, query)
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️levenshtein](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/levenshtein)
// levenshtein holds the data fields for a levenshtein record.
// levenshtein MUST perform the levenshtein operation.
func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	curr := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		curr[0] = i
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			ins := curr[j-1] + 1
			del := prev[j] + 1
			sub := prev[j-1] + cost
			m := ins
			if del < m {
				m = del
			}
			if sub < m {
				m = sub
			}
			curr[j] = m
		}
		prev, curr = curr, prev
	}
	return prev[lb]
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️fuzzycontains](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/fuzzyContains)
// fuzzyContains holds the data fields for a fuzzyContains record.
// fuzzyContains MUST perform the fuzzyContains operation.
func fuzzyContains(text, term string) bool {
	if strings.Contains(text, term) {
		return true
	}
	maxDist := 1
	if len(term) > 5 {
		maxDist = 2
	}
	words := strings.Fields(text)
	for _, w := range words {
		if levenshtein(w, term) <= maxDist {
			return true
		}
		if len(w) >= len(term) {
			for i := 0; i <= len(w)-len(term)+maxDist && i <= len(w)-1; i++ {
				end := i + len(term) + maxDist
				if end > len(w) {
					end = len(w)
				}
				sub := w[i:end]
				if levenshtein(sub, term) <= maxDist {
					return true
				}
			}
		}
	}
	return false
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️searchtreeinmemory](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/searchTreeInMemory)
// searchTreeInMemory holds the data fields for a searchTreeInMemory record.
// searchTreeInMemory MUST perform the searchTreeInMemory operation.
func searchTreeInMemory(root *TreeNode, query string) *TreeNode {
	terms := strings.Fields(strings.ToLower(query))
	if len(terms) == 0 {
		return root
	}
	matchedIDs := make(map[string]bool)
	serializeNodeData := func(data map[string]interface{}) string {
		if len(data) == 0 {
			return ""
		}
		parts := make([]string, 0, len(data))
		for _, value := range data {
			switch typed := value.(type) {
			case string:
				parts = append(parts, typed)
			case []string:
				parts = append(parts, strings.Join(typed, " "))
			case []interface{}:
				var values []string
				for _, item := range typed {
					values = append(values, fmt.Sprint(item))
				}
				parts = append(parts, strings.Join(values, " "))
			default:
				parts = append(parts, fmt.Sprint(typed))
			}
		}
		return strings.Join(parts, " ")
	}
	var walk func(node *TreeNode)
	walk = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			docID := node.ID
			if docID == "" {
				docID = node.Label
			}
			text := strings.ToLower(strings.Join([]string{
				node.Label,
				node.ID,
				node.SubKind,
				node.Description,
				node.URI,
				node.Status,
				node.Contributor,
				string(node.Kind),
				serializeNodeData(node.Data),
			}, " "))
			allMatch := true
			for _, term := range terms {
				if !fuzzyContains(text, term) {
					allMatch = false
					break
				}
			}
			if allMatch {
				matchedIDs[docID] = true
			}
		}
		for _, c := range node.Children {
			walk(c)
		}
	}
	walk(root)
	if len(matchedIDs) == 0 {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	pruned := pruneUnmatched(root, matchedIDs)
	if pruned == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	return pruned
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️pruneunmatched](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/pruneUnmatched)
// pruneUnmatched holds the data fields for a pruneUnmatched record.
// pruneUnmatched MUST perform the pruneUnmatched operation.
func pruneUnmatched(node *TreeNode, matchedIDs map[string]bool) *TreeNode {
	return pruneUnmatchedInner(node, matchedIDs, false)
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️pruneunmatchedinner](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/pruneUnmatchedInner)
// pruneUnmatchedInner holds the data fields for a pruneUnmatchedInner record.
// pruneUnmatchedInner MUST perform the pruneUnmatchedInner operation.
func pruneUnmatchedInner(node *TreeNode, matchedIDs map[string]bool, ancestorMatched bool) *TreeNode {
	docID := node.ID
	if docID == "" {
		docID = node.Label
	}
	selfMatched := matchedIDs[docID]
	keepDescendants := ancestorMatched || selfMatched
	var kept []*TreeNode
	for _, c := range node.Children {
		fc := pruneUnmatchedInner(c, matchedIDs, keepDescendants)
		if fc != nil {
			kept = append(kept, fc)
		}
	}
	if keepDescendants || len(kept) > 0 || node.Kind == TreeNodeCategory {
		if node.Kind == TreeNodeCategory && len(kept) == 0 && !selfMatched && !ancestorMatched {
			return nil
		}
		copy := *node
		copy.Children = kept
		return &copy
	}
	return nil
}

// RenderMonorepoTree MUST produce a complete monorepo tree output.
// RenderMonorepoTree renders the monorepo tree into its output representation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖treelogic🔖monorepotree🛠️rendermonorepotree](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Monorepo%20Tree/d/i/RenderMonorepoTree)
func RenderMonorepoTree(root *TreeNode) string {
	var sb strings.Builder
	for i, c := range root.Children {
		renderTreeNodeText(&sb, c, "", i == len(root.Children)-1, true)
	}
	return sb.String()
}

