// HumanRenderer holds the data fields for a human renderer record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers✂️humanrenderer](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/HumanRenderer)
type HumanRenderer struct {
	Verbose bool
}

// Render MUST produce a complete  output.
// Render renders the  into its output representation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🛠️render](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/Render)
func (r HumanRenderer) Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error) {
	exitCode := 0
	isTTY := false
	if f, ok := out.(*os.File); ok {
		stat, _ := f.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			isTTY = true
		}
	}

	if os.Getenv("NO_COLOR") != "" {
		isTTY = false
	}

	startTime := time.Now()

	for event := range stream {
		if event.Kind == KindDone && event.Done != nil {
			exitCode = event.Done.ExitCode
			duration := time.Since(startTime).Round(time.Millisecond)

			var summary string
			if exitCode != 0 {
				summary = renderTemplate(textTpl, "text/done_failure", map[string]interface{}{
					"IsTTY":    isTTY,
					"Command":  event.Command,
					"Duration": duration,
					"ExitCode": exitCode,
				})
			} else {
				summary = renderTemplate(textTpl, "text/done_success", map[string]interface{}{
					"IsTTY":    isTTY,
					"Command":  event.Command,
					"Duration": duration,
				})
			}

			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(out, summary)
			continue
		}
		if event.Kind == KindError && event.Error != nil {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(errOut, renderTemplate(textTpl, "text/error", map[string]interface{}{
				"IsTTY":   isTTY,
				"Message": event.Error.Message,
			}))
			if r.Verbose && event.Error.Detail != "" {
				fmt.Fprintln(errOut, renderTemplate(textTpl, "text/error_detail", map[string]interface{}{
					"Detail": event.Error.Detail,
				}))
			}
			continue
		}
		if event.Kind == KindLog && event.Message != "" {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(errOut, renderTemplate(textTpl, "text/log", map[string]interface{}{
				"IsTTY":   isTTY,
				"Message": event.Message,
			}))
			continue
		}
		if event.Kind == KindResult && len(event.Data) > 0 {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprint(out, formatResult(event.Command, event.Data, isTTY))
		}
		if event.Kind == KindProgress && event.Progress != nil {
			if isTTY {
				fmt.Fprint(out, renderTemplate(textTpl, "text/progress_tty", map[string]interface{}{
					"Percent": event.Progress.Percent,
					"Current": event.Progress.Current,
					"Total":   event.Progress.Total,
					"Step":    event.Progress.Step,
				}))
			} else {
				if event.Progress.Percent%10 == 0 && event.Progress.Percent > 0 {
					fmt.Fprintln(out, renderTemplate(textTpl, "text/progress", map[string]interface{}{
						"Percent": event.Progress.Percent,
						"Step":    event.Progress.Step,
					}))
				}
			}
		}
	}
	return exitCode, nil
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🛠️formatresult](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/formatResult)
// formatResult MUST perform the formatResult operation.
// formatResult performs the formatResult operation.
func formatResult(command string, data json.RawMessage, isTTY bool) string {
	var raw map[string]interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return renderTemplate(textTpl, "text/result_fallback", map[string]interface{}{
			"IsTTY": isTTY,
			"Data":  string(data),
		}) + "\n"
	}
	payload := raw
	if inner, ok := raw["data"].(map[string]interface{}); ok {
		payload = inner
	}

	var sb strings.Builder

	if output, ok := payload["markdown"].(string); ok {
		return output
	}

	if analyze, ok := payload["analyze"].(map[string]interface{}); ok {
		if metrics, ok := analyze["metrics"].(map[string]interface{}); ok {
			total := metrics["total"]
			autofixable := metrics["autofixable"]
			sb.WriteString(renderTemplate(textTpl, "text/analyze_summary", map[string]interface{}{
				"IsTTY":       isTTY,
				"Total":       total,
				"Autofixable": autofixable,
			}) + "\n")
		}
		if breachs, ok := analyze["breachs"].([]interface{}); ok {
			for _, v := range breachs {
				if vio, ok := v.(map[string]interface{}); ok {
					kind := ""
					if k, ok := vio["kind"].(map[string]interface{}); ok {
						kind = fmt.Sprintf("%v", k["id"])
					} else if kStr, ok := vio["kind"].(string); ok {
						kind = kStr
					}
					scope := fmt.Sprintf("%v", vio["scope"])
					line := fmt.Sprintf("%v", vio["line"])
					summary := fmt.Sprintf("%v", vio["summary"])
					sb.WriteString(renderTemplate(textTpl, "text/breach", map[string]interface{}{
						"IsTTY":   isTTY,
						"Kind":    kind,
						"Scope":   scope,
						"Line":    line,
						"Summary": summary,
					}) + "\n")
				}
			}
		}
		if sb.Len() > 0 {
			return sb.String()
		}
	}

	if fix, ok := payload["fix"].(map[string]interface{}); ok {
		fixed := fix["fixed"]
		remaining := fix["remaining"]
		return renderTemplate(textTpl, "text/fix", map[string]interface{}{
			"IsTTY":     isTTY,
			"Fixed":     fixed,
			"Remaining": remaining,
		}) + "\n"
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		goals, goalsOk := repo["goals"].([]interface{})
		tickets, _ := repo["tickets"].([]interface{})
		if goalsOk {
			return renderGoalTree(goals, tickets, isTTY, false)
		}
	}

	termWidth := 0
	if isTTY {
		termWidth = getTerminalWidth()
	}

	renderList := func(kind string, items []interface{}) (string, bool) {
		if len(items) == 0 {
			return "", true
		}
		var b strings.Builder
		for _, it := range items {
			if m, ok := it.(map[string]interface{}); ok {
				line := renderEntityHuman(kind, m, isTTY)
				if termWidth > 0 {
					line = truncateANSI(line, termWidth)
				}
				b.WriteString(line)
				b.WriteString("\n")
			}
		}
		return b.String(), true
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		listKindPairs := []struct {
			key  string
			kind string
		}{
			{"tickets", "ticket"},
			{"goals", "goal"},
			{"bundles", "bundle"},
			{"technologies", "technology"},
			{"folders", "folder"},
			{"files", "file"},
			{"contributors", "contributor"},
			{"policies", "policy"},
			{"statutes", "statute"},
		}
		for _, lk := range listKindPairs {
			if items, ok := repo[lk.key].([]interface{}); ok {
				out, _ := renderList(lk.kind, items)
				return out
			}
		}
	}

	topListPairs := []struct {
		key  string
		kind string
	}{
		{"todos", "todo"},
		{"sections", "section"},
		{"definitions", "definition"},
		{"drafts", "draft"},
	}
	for _, lk := range topListPairs {
		if items, ok := payload[lk.key].([]interface{}); ok {
			out, _ := renderList(lk.kind, items)
			return out
		}
	}

	singleKeys := []string{
		"ticket", "goal", "bundle", "folder", "policy",
		"contributor", "draft", "todo", "technology", "definition",
	}
	for _, key := range singleKeys {
		if entity, ok := payload[key].(map[string]interface{}); ok {
			if topID, ok := payload["id"].(string); ok {
				if _, has := entity["id"]; !has {
					entity["id"] = topID
				}
			}
			return renderEntityHuman(key, entity, isTTY) + "\n"
		}
	}

	if file, ok := payload["file"].(map[string]interface{}); ok {
		line := renderEntityHuman("file", file, isTTY)
		if termWidth > 0 {
			line = truncateANSI(line, termWidth)
		}
		sb.WriteString(line + "\n")
		if sections, ok := file["sections"].([]interface{}); ok {
			var printSections func(items []interface{}, indent string)
			printSections = func(items []interface{}, indent string) {
				for _, item := range items {
					if sec, ok := item.(map[string]interface{}); ok {
						secStr := renderEntityHuman("section", sec, isTTY)
						if termWidth > 0 {
							secStr = truncateANSI(secStr, termWidth)
						}
						sb.WriteString(indent + secStr + "\n")
						if children, ok := sec["children"].([]interface{}); ok && len(children) > 0 {
							printSections(children, indent+"  ")
						}
					}
				}
			}
			printSections(sections, "  ")
		}
		if definitions, ok := file["definitions"].([]interface{}); ok {
			for _, d := range definitions {
				if def, ok := d.(map[string]interface{}); ok {
					defStr := renderEntityHuman("definition", def, isTTY)
					if termWidth > 0 {
						defStr = truncateANSI(defStr, termWidth)
					}
					sb.WriteString("  " + defStr + "\n")
				}
			}
		}
		if sb.Len() > 0 {
			return sb.String()
		}
	}

	if sec, ok := payload["section"].(map[string]interface{}); ok {
		b, _ := json.Marshal(sec)
		var s Section
		json.Unmarshal(b, &s)
		return renderSectionTree(&s, isTTY, false)
	}

	for key, val := range payload {
		if entityMap, ok := val.(map[string]interface{}); ok {
			kind := inferEntityKind(key)
			if kind != "" {
				return renderEntityHuman(kind, entityMap, isTTY) + "\n"
			}
		}
	}

	if id, ok := payload["id"].(string); ok {
		if path, ok := payload["path"].(string); ok {
			return renderTemplate(textTpl, "text/id_path", map[string]interface{}{
				"IsTTY": isTTY,
				"ID":    id,
				"Path":  path,
			}) + "\n"
		}
		return renderTemplate(textTpl, "text/id_only", map[string]interface{}{
			"IsTTY": isTTY,
			"ID":    id,
		}) + "\n"
	}

	return renderEntityHuman("root", payload, isTTY) + "\n"
}

// MarkdownRenderer holds the data fields for a markdown renderer record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers✂️markdownrenderer](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/MarkdownRenderer)
type MarkdownRenderer struct{}

// Render MUST produce a complete  output.
// Render renders the  into its output representation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🛠️render](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/Render)
func (r MarkdownRenderer) Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error) {
	exitCode := 0
	for event := range stream {
		if event.Kind == KindDone && event.Done != nil {
			exitCode = event.Done.ExitCode
			continue
		}
		if event.Kind == KindResult && len(event.Data) > 0 {
			fmt.Fprint(out, formatMarkdownResult(event.Command, event.Data))
		}
		if event.Kind == KindError && event.Error != nil {
			fmt.Fprintln(errOut, renderTemplate(mdTpl, "md/error", map[string]interface{}{
				"Message": event.Error.Message,
			}))
			if event.Error.Detail != "" {
				fmt.Fprintln(errOut, renderTemplate(mdTpl, "md/error_detail", map[string]interface{}{
					"Detail": event.Error.Detail,
				}))
			}
		}
	}
	return exitCode, nil
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🛠️formatmarkdownresult](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/formatMarkdownResult)
// formatMarkdownResult holds the data fields for a formatMarkdownResult record.
// formatMarkdownResult MUST perform the formatMarkdownResult operation.
func formatMarkdownResult(command string, data json.RawMessage) string {
	var raw map[string]interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return renderEntityMarkdownLink("root", map[string]interface{}{"name": string(data)}) + "\n"
	}
	payload := raw
	if inner, ok := raw["data"].(map[string]interface{}); ok {
		payload = inner
	}

	var sb strings.Builder

	if markdown, ok := payload["markdown"].(string); ok {
		return markdown
	}

	if analyze, ok := payload["analyze"].(map[string]interface{}); ok {
		if metrics, ok := analyze["metrics"].(map[string]interface{}); ok {
			total := metrics["total"]
			autofixable := metrics["autofixable"]
			sb.WriteString(renderTemplate(mdTpl, "md/analyze_total", map[string]interface{}{
				"Total": total,
			}) + "\n")
			if autofixable != nil {
				sb.WriteString(renderTemplate(mdTpl, "md/analyze_autofixable", map[string]interface{}{
					"Autofixable": autofixable,
				}) + "\n")
			}
		}
		if breachs, ok := analyze["breachs"].([]interface{}); ok {
			for _, v := range breachs {
				if vio, ok := v.(map[string]interface{}); ok {
					kind := ""
					if k, ok := vio["kind"].(map[string]interface{}); ok {
						kind = fmt.Sprintf("%v", k["id"])
					} else if kStr, ok := vio["kind"].(string); ok {
						kind = kStr
					}
					scope := fmt.Sprintf("%v", vio["scope"])
					line := fmt.Sprintf("%v", vio["line"])
					summary := fmt.Sprintf("%v", vio["summary"])
					sb.WriteString(renderTemplate(mdTpl, "md/breach", map[string]interface{}{
						"Kind":    kind,
						"Scope":   scope,
						"Line":    line,
						"Summary": summary,
					}) + "\n")
				}
			}
		}
		return sb.String()
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		goals, goalsOk := repo["goals"].([]interface{})
		tickets, _ := repo["tickets"].([]interface{})
		if goalsOk {
			return renderGoalTree(goals, tickets, false, true)
		}
	}

	listKeys := []struct {
		wrap string
		key  string
		kind string
	}{
		{"repo", "tickets", "ticket"},
		{"repo", "goals", "goal"},
		{"repo", "bundles", "bundle"},
		{"repo", "technologies", "technology"},
		{"repo", "folders", "folder"},
		{"repo", "files", "file"},
		{"repo", "contributors", "contributor"},
		{"repo", "policies", "policy"},
		{"repo", "statutes", "statute"},
		{"", "todos", "todo"},
		{"", "sections", "section"},
		{"", "definitions", "definition"},
		{"", "drafts", "draft"},
	}
	for _, lk := range listKeys {
		var container map[string]interface{}
		if lk.wrap != "" {
			if w, ok := payload[lk.wrap].(map[string]interface{}); ok {
				container = w
			}
		} else {
			container = payload
		}
		if container == nil {
			continue
		}
		if items, ok := container[lk.key].([]interface{}); ok {
			for _, item := range items {
				if m, ok := item.(map[string]interface{}); ok {
					sb.WriteString(renderEntityMarkdown(lk.kind, m) + "\n")
				}
			}
			return sb.String()
		}
	}

	isList := strings.HasSuffix(command, " list") || strings.HasSuffix(command, " tree")

	singleKeys := []string{
		"ticket", "goal", "bundle", "folder", "file", "definition",
		"contributor", "policy", "technology", "draft", "todo", "checkpoint",
	}
	for _, key := range singleKeys {
		if entity, ok := payload[key].(map[string]interface{}); ok {
			if topID, ok := payload["id"].(string); ok {
				if _, has := entity["id"]; !has {
					entity["id"] = topID
				}
			}
			if key == "file" && !isList {
				return formatMarkdownFile(entity)
			}
			if key == "section" {
				b, _ := json.Marshal(entity)
				var s Section
				json.Unmarshal(b, &s)
				return renderSectionTree(&s, false, true)
			}
			if isList {
				return renderEntityMarkdown(key, entity) + "\n"
			}
			return renderEntityMarkdownLink(key, entity) + "\n"
		}
	}

	if sec, ok := payload["section"].(map[string]interface{}); ok {
		b, _ := json.Marshal(sec)
		var s Section
		json.Unmarshal(b, &s)
		return renderSectionTree(&s, false, true)
	}

	for key, val := range payload {
		if entityMap, ok := val.(map[string]interface{}); ok {
			kind := inferEntityKind(key)
			if kind != "" {
				return renderEntityMarkdownLink(kind, entityMap) + "\n"
			}
		}
	}

	return renderEntityMarkdownLink("root", payload) + "\n"
}

// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🛠️formatmarkdownfile](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/formatMarkdownFile)
// formatMarkdownFile holds the data fields for a formatMarkdownFile record.
// formatMarkdownFile MUST perform the formatMarkdownFile operation.
func formatMarkdownFile(file map[string]interface{}) string {
	var sb strings.Builder
	sb.WriteString(renderEntityMarkdownLink("file", file) + "\n")

	filePath, _ := file["path"].(string)
	if id, ok := file["id"].(string); ok && id != "" {
		filePath = id
	}

	if sections, ok := file["sections"].([]interface{}); ok {
		var printSections func(items []interface{}, indent string)
		printSections = func(items []interface{}, indent string) {
			for _, item := range items {
				if sec, ok := item.(map[string]interface{}); ok {
					if _, hasPath := sec["filePath"]; !hasPath {
						sec["filePath"] = filePath
					}
					line := renderEntityMarkdown("section", sec)
					sb.WriteString(fmt.Sprintf("%s%s\n", indent, line))
					if children, ok := sec["children"].([]interface{}); ok && len(children) > 0 {
						printSections(children, indent+"  ")
					}
				}
			}
		}
		printSections(sections, "  ")
	}

	if definitions, ok := file["definitions"].([]interface{}); ok {
		for _, d := range definitions {
			if def, ok := d.(map[string]interface{}); ok {
				if _, hasPath := def["filePath"]; !hasPath {
					def["filePath"] = filePath
				}
				sb.WriteString("  " + renderEntityMarkdown("definition", def) + "\n")
			}
		}
	}
	return sb.String()
}

// renderStream holds the data fields for a renderStream record.
// renderStream MUST perform the renderStream operation.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🪨renderstream](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/renderStream)
func renderStream(cmd *cobra.Command, config *Config, stream <-chan Event) error {
	var renderer StreamRenderer
	if config.IsJSON() {
		renderer = NDJSONRenderer{}
	} else if config.IsMarkdown() {
		renderer = MarkdownRenderer{}
	} else {
		renderer = HumanRenderer{Verbose: config.Verbose}
	}

	exitCode, err := renderer.Render(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), stream)
	if err != nil {
		return err
	}
	if exitCode != 0 {
		return ExitError{Code: exitCode}
	}
	return nil
}

// renderEventsToMarkdown MUST perform the renderEventsToMarkdown operation.
// renderEventsToMarkdown holds the data fields for a renderEventsToMarkdown record.
// [🧰repo⌨️cli💻main🔖cliadapter🔖clirenderers🪨rendereventstomarkdown](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/CLI%20Renderers/d/i/renderEventsToMarkdown)
func renderEventsToMarkdown(events []Event) string {
	var sb strings.Builder
	for _, event := range events {
		if event.Kind == KindResult && len(event.Data) > 0 {
			sb.WriteString(formatMarkdownResult(event.Command, event.Data))
		}
		if event.Kind == KindError && event.Error != nil {
			sb.WriteString(renderTemplate(mdTpl, "md/error", map[string]interface{}{
				"Message": event.Error.Message,
			}) + "\n")
		}
	}
	return sb.String()
}

