// findRepoRoot MUST perform the findRepoRoot operation.
// [🧰repo⌨️cli💻main🔖types🔖utils🛠️findreporoot](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/findRepoRoot)
// findRepoRoot performs the findRepoRoot operation.
func findRepoRoot(startDir string) string {
	if strings.TrimSpace(startDir) == "" {
		cwd, err := os.Getwd()
		if err != nil {
			return "."
		}
		startDir = cwd
	}
	dir, err := filepath.Abs(startDir)
	if err != nil {
		return startDir
	}

	searchDir := dir
	for {
		if FileExists(filepath.Join(searchDir, "repo", "cli", "main.go")) {
			return searchDir
		}
		parent := filepath.Dir(searchDir)
		if parent == searchDir {
			break
		}
		searchDir = parent
	}

	searchDir = dir
	for {
		if _, err := os.Stat(filepath.Join(searchDir, ".git")); err == nil {
			return searchDir
		}
		parent := filepath.Dir(searchDir)
		if parent == searchDir {
			break
		}
		searchDir = parent
	}

	searchDir = dir
	for {
		if _, err := os.Stat(filepath.Join(searchDir, "go.mod")); err == nil {
			return searchDir
		}
		parent := filepath.Dir(searchDir)
		if parent == searchDir {
			return dir
		}
		searchDir = parent
	}
}

