// formatterPlansForLanguage MUST perform the formatterPlansForLanguage operation.
// formatterPlansForLanguage holds the data fields for a formatterPlansForLanguage record.
// [🧰repo⌨️cli💻main🔖types🔖utils🛠️formatterplansforlanguage](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/formatterPlansForLanguage)
func formatterPlansForLanguage(languageName string, relPath string) []formatterPlan {
	prettierBinary := filepath.Join("node_modules", ".bin", "prettier")
	prettierPlan := formatterPlan{
		binary:      prettierBinary,
		args:        []string{"--write", "--ignore-unknown", relPath},
		requirement: []string{prettierBinary, ".prettierrc.json"},
	}
	switch languageName {
	case "typescript", "markdown", "json", "yaml", "graphql", "sql", "toml":
		return []formatterPlan{prettierPlan}
	case "go":
		return []formatterPlan{
			{binary: "gofmt", args: []string{"-w", relPath}, requirement: []string{"go.work"}},
		}
	case "python":
		return []formatterPlan{
			{binary: "uv", args: []string{"run", "--group", "dev", "ruff", "format", relPath}, requirement: []string{"pyproject.toml"}},
			{binary: "uv", args: []string{"run", "--group", "dev", "black", relPath}, requirement: []string{"pyproject.toml"}},
			prettierPlan,
		}
	case "csharp":
		return []formatterPlan{
			{binary: "dotnet", args: []string{"format", "Monorepo.sln", "--include", relPath, "--verbosity", "minimal"}, requirement: []string{"Monorepo.sln"}},
			prettierPlan,
		}
	case "rust":
		return []formatterPlan{
			{binary: "rustfmt", args: []string{relPath}, requirement: []string{"Cargo.toml"}},
			prettierPlan,
		}
	case "ruby":
		return []formatterPlan{
			{binary: "rubocop", args: []string{"-A", relPath}, requirement: []string{"package.json"}},
			prettierPlan,
		}
	case "shell":
		return []formatterPlan{
			{binary: "shfmt", args: []string{"-w", relPath}, requirement: []string{"package.json"}},
			prettierPlan,
		}
	default:
		return []formatterPlan{prettierPlan}
	}
}

// [🧰repo⌨️cli💻main🔖types🔖utils🛠️isformatterplanavailable](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/isFormatterPlanAvailable)
// isFormatterPlanAvailable holds the data fields for a isFormatterPlanAvailable record.
// isFormatterPlanAvailable MUST perform the isFormatterPlanAvailable operation.
func isFormatterPlanAvailable(plan formatterPlan, workDir string) bool {
	if strings.Contains(plan.binary, "/") || strings.Contains(plan.binary, "\\") {
		if !FileExists(filepath.Join(workDir, plan.binary)) {
			return false
		}
	} else {
		if _, err := formatterBinaryLookup(plan.binary); err != nil {
			return false
		}
	}
	for _, rel := range plan.requirement {
		if !FileExists(filepath.Join(workDir, rel)) {
			return false
		}
	}
	return true
}

// [🧰repo⌨️cli💻main🔖types🔖utils🛠️fallbackformattext](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/fallbackFormatText)
// fallbackFormatText holds the data fields for a fallbackFormatText record.
// fallbackFormatText MUST perform the fallbackFormatText operation.
func fallbackFormatText(content string) string {
	lines := strings.Split(content, "\n")
	for i, line := range lines {
		lines[i] = strings.TrimRight(line, " \t")
	}
	formatted := strings.Join(lines, "\n")
	if formatted == "" {
		return formatted
	}
	if !strings.HasSuffix(formatted, "\n") {
		formatted += "\n"
	}
	return formatted
}

// [🧰repo⌨️cli💻main🔖types🔖utils🛠️runformatterafterautofix](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/runFormatterAfterAutofix)
// runFormatterAfterAutofix holds the data fields for a runFormatterAfterAutofix record.
// runFormatterAfterAutofix MUST perform the runFormatterAfterAutofix operation.
func runFormatterAfterAutofix(relPath string, language LanguagePlugin) error {
	absPath := filepath.Join(rootDir, relPath)
	langName := ""
	if language != nil {
		langName = language.Name()
	}
	plans := formatterPlansForLanguage(langName, relPath)
	for _, plan := range plans {
		if !isFormatterPlanAvailable(plan, rootDir) {
			continue
		}
		if err := formatterCommandRun(plan.binary, plan.args, rootDir); err == nil {
			return nil
		}
	}
	content, err := ReadTextFile(absPath)
	if err != nil {
		return err
	}
	formatted := fallbackFormatText(content)
	if formatted == content {
		return nil
	}
	return WriteTextFile(absPath, formatted)
}

// runFormatterForFile runs the language-appropriate formatter on the given file.
// Unlike runFormatterAfterAutofix, this only runs the formatter with no fallback.
// [🧰repo⌨️cli💻main🔖types🔖utils🛠️runformatterforfile](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/runFormatterForFile)
func runFormatterForFile(relPath string) {
	lang := GetLanguage(relPath)
	langName := ""
	if lang != nil {
		langName = lang.Name()
	}
	plans := formatterPlansForLanguage(langName, relPath)
	for _, plan := range plans {
		if !isFormatterPlanAvailable(plan, rootDir) {
			continue
		}
		if err := formatterCommandRun(plan.binary, plan.args, rootDir); err == nil {
			return
		}
	}
}

