// [🧰repo⌨️cli💻main🔖types🔖policies🛠️folderpolicy](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/folderPolicy)
// folderPolicy holds the data fields for a folderPolicy record.
// folderPolicy MUST perform the folderPolicy operation.
func folderPolicy(ctx *PolicyContext) []Breach {
	if ctx.Scope.Kind != ScopeRepo {
		return nil
	}
	var breachs []Breach
	excludePrefixes := []string{
		".git/",
		".repo/",
		"node_modules/",
		".venv/",
		".nx/",
	}

	err := filepath.WalkDir(ctx.RootDir, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if !d.IsDir() {
			return nil
		}
		relPath, _ := filepath.Rel(ctx.RootDir, path)
		relPath = NormalizePath(relPath)
		if relPath == "." {
			return nil
		}
		for _, prefix := range excludePrefixes {
			if strings.HasPrefix(relPath+"/", prefix) {
				return filepath.SkipDir
			}
		}

		if isIgnoredByGitignore(filepath.Join(ctx.RootDir, relPath)) {
			return filepath.SkipDir
		}

		f, readErr := os.Open(path)
		if readErr != nil {
			return nil
		}
		defer f.Close()
		_, readErr = f.Readdirnames(1)
		if readErr == io.EOF {
			breachs = append(breachs, ctx.CreateBreach(
				"Empty folder \""+relPath+"\" must be removed",
				BreachFolderIllegalEmpty,
				relPath+"/", 0, 0, relPath))
		}
		return nil
	})
	_ = err
	return breachs
}

// [🧰repo⌨️cli💻main🔖types🔖policies✂️godfile](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/Godfile)
// Godfile holds the data fields for a Godfile record.
type Godfile struct {
	Exact map[string]bool
	Globs []string
}

// [🧰repo⌨️cli💻main🔖types🔖policies🛠️isglobpattern](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/isGlobPattern)
// isGlobPattern holds the data fields for a isGlobPattern record.
// isGlobPattern MUST perform the isGlobPattern operation.
func isGlobPattern(value string) bool {
	return strings.ContainsAny(value, "*?[{")
}

// [🧰repo⌨️cli💻main🔖types🔖policies🛠️loadgodfile](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/loadGodfile)
// loadGodfile holds the data fields for a loadGodfile record.
// loadGodfile MUST perform the loadGodfile operation.
func loadGodfile() (*Godfile, error) {
	godfilePath := filepath.Join(rootDir, ".repo", "files.json")
	data, err := os.ReadFile(godfilePath)
	if err != nil {
		return nil, err
	}
	var files []string
	if err := json.Unmarshal(data, &files); err != nil {
		return nil, err
	}
	result := &Godfile{
		Exact: make(map[string]bool, len(files)),
	}
	for _, f := range files {
		normalized := NormalizePath(f)
		if isGlobPattern(normalized) {
			result.Globs = append(result.Globs, normalized)
			continue
		}
		result.Exact[normalized] = true
	}
	return result, nil
}

// [🧰repo⌨️cli💻main🔖types🔖policies🛠️godfilematchespath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/godfileMatchesPath)
// godfileMatchesPath holds the data fields for a godfileMatchesPath record.
// godfileMatchesPath MUST perform the godfileMatchesPath operation.
func godfileMatchesPath(godfile *Godfile, relPath string) bool {
	relPath = normalizeRepoPath(relPath)
	if godfile.Exact[relPath] {
		return true
	}
	for _, pattern := range godfile.Globs {
		matched, err := doublestar.Match(pattern, relPath)
		if err != nil {
			continue
		}
		if matched {
			return true
		}
	}
	return false
}

// [🧰repo⌨️cli💻main🔖types🔖policies🛠️filepolicy](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/filePolicy)
// filePolicy holds the data fields for a filePolicy record.
// filePolicy MUST perform the filePolicy operation.
func filePolicy(ctx *PolicyContext) []Breach {
	if ctx.Scope.Kind != ScopeRepo {
		return nil
	}
	var breachs []Breach
	godfile, err := loadGodfile()
	if err != nil {
		return breachs
	}
	_ = filepath.WalkDir(rootDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if isRepoExcludedPath(path) || strings.HasPrefix(d.Name(), ".git") || d.Name() == "node_modules" || d.Name() == ".venv" {
				return filepath.SkipDir
			}
			return nil
		}
		if isRepoExcludedPath(path) || isGitIgnored(path) {
			return nil
		}
		relPath := normalizeRepoPath(path)
		if !godfileMatchesPath(godfile, relPath) {
			breachs = append(breachs, ctx.CreateBreach(
				"File \""+relPath+"\" is not listed in .repo/files.json",
				BreachFileIllegalUseGodfile,
				relPath, 0, 0, relPath))
		}
		return nil
	})
	return breachs
}

// [🧰repo⌨️cli💻main🔖types🔖policies🛠️semiopolicy](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Policies/d/i/semioPolicy)
// semioPolicy validates that semio.* files do not import UI dependencies.
func semioPolicy(ctx *PolicyContext) []Breach {
	var breachs []Breach
	files, err := ctx.Files()
	if err != nil {
		return breachs
	}
	uiPackages := []string{
		"clsx", "tailwind-merge", "tailwind", "tailwindcss",
		"three", "@react-three",
		"react", "react-dom",
		"framer-motion", "lucide-react",
		"@radix-ui", "@radix-client",
		"@dnd-kit",
		"zustand",
		"elements/ui",
	}
	for _, file := range files {
		baseName := filepath.Base(file)
		if !strings.HasPrefix(baseName, "semio.") {
			continue
		}
		if !strings.HasSuffix(file, ".ts") && !strings.HasSuffix(file, ".tsx") {
			continue
		}
		content := ctx.ReadText(file)
		if content == "" {
			continue
		}
		lines := strings.Split(content, "\n")
		for lineNum, line := range lines {
			lineNumber := lineNum + 1
			if !strings.Contains(line, "import ") {
				continue
			}
			for _, pkg := range uiPackages {
				importPattern := fmt.Sprintf(`from\s+['"].*%s`, regexp.QuoteMeta(pkg))
				if matched, _ := regexp.MatchString(importPattern, line); matched {
					breachs = append(breachs, ctx.CreateBreach(
						fmt.Sprintf("UI dependency '%s' is not allowed in semio.* files", pkg),
						BreachSemioNoUiDependency,
						file, lineNumber, 0, strings.TrimSpace(line)))
					break
				}
			}
		}
	}
	return ctx.FilterIgnored(breachs)
}

