// ToolFolderList MUST complete the operation successfully.
// ToolFolderList performs the tool folder list operation.
// [🧰repo⌨️cli💻main🔖types🔖tickets🛠️toolfolderlist](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/ToolFolderList)
func ToolFolderList(path string) ToolResult {
	output := NewOutput()
	absPath := filepath.Join(rootDir, strings.TrimSuffix(path, "/"))
	if !FileExists(absPath) {
		return toolErrorMsg(fmt.Sprintf("Folder not found: %s", path))
	}
	folders, err := ListDirEntries(absPath, true)
	if err != nil {
		return toolErrorResult(err)
	}
	var relPaths []string
	for _, f := range folders {
		relPaths = append(relPaths, NormalizePath(filepath.Join(path, f)))
	}
	ignored := GetGitIgnoredSet(relPaths)
	var filtered []string
	for _, f := range folders {
		relPath := NormalizePath(filepath.Join(path, f))
		if !ignored[relPath] && !ignored[relPath+"/"] {
			filtered = append(filtered, f)
		}
	}
	output.Info(fmt.Sprintf("\n📁Found %d folders in %s:\n", len(filtered), path))
	for _, f := range filtered {
		output.Plain(fmt.Sprintf("   %s/", f))
	}
	return ToolResult{Output: *output, Data: filtered}
}

// ToolFolderTree MUST complete the operation successfully.
// ToolFolderTree performs the tool folder tree operation.
// [🧰repo⌨️cli💻main🔖types🔖tickets🛠️toolfoldertree](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/ToolFolderTree)
func ToolFolderTree(path string) ToolResult {
	output := NewOutput()
	absPath := filepath.Join(rootDir, strings.TrimSuffix(path, "/"))
	if !FileExists(absPath) {
		return toolErrorMsg(fmt.Sprintf("Folder not found: %s", path))
	}
	output.Info(fmt.Sprintf("\n📁Folder tree: %s\n", path))
	printTree(output, absPath, "")
	return ToolResult{Output: *output}
}

// [🧰repo⌨️cli💻main🔖types🔖tickets🛠️printtree](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/printTree)
// printTree holds the data fields for a printTree record.
// printTree MUST perform the printTree operation.
func printTree(output *CommandOutput, dir, prefix string) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	var items []os.DirEntry
	for _, e := range entries {
		if !strings.HasPrefix(e.Name(), ".") {
			items = append(items, e)
		}
	}
	var relPaths []string
	for _, e := range items {
		relPaths = append(relPaths, GetRelativePath(filepath.Join(dir, e.Name())))
	}
	ignored := GetGitIgnoredSet(relPaths)
	var filtered []os.DirEntry
	for _, e := range items {
		relPath := GetRelativePath(filepath.Join(dir, e.Name()))
		if !ignored[relPath] && !ignored[relPath+"/"] {
			filtered = append(filtered, e)
		}
	}
	for i, e := range filtered {
		isLast := i == len(filtered)-1
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		suffix := ""
		if e.IsDir() {
			suffix = "/"
		}
		output.Plain(fmt.Sprintf("%s%s%s%s", prefix, connector, e.Name(), suffix))
		if e.IsDir() {
			newPrefix := prefix + "│   "
			if isLast {
				newPrefix = prefix + "    "
			}
			printTree(output, filepath.Join(dir, e.Name()), newPrefix)
		}
	}
}

