// GetFolders MUST retrieve the requested value or return an error.
// GetFolders retrieves and returns the folders.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️getfolders](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/GetFolders)
func (c *repoContext) GetFolders() []*Folder {
	ctx := NewCodebaseContext()
	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err != nil {
		return []*Folder{}
	}
	folders := BuildCodebaseFolders(ctx)
	results := make([]*Folder, 0, len(folders))
	for _, entry := range folders {
		parent := filepath.Dir(entry.Path)
		var parentID *string
		if parent != "." {
			pid := ctx.GetFolderID(parent)
			parentID = &pid
		}
		bundleID := ctx.GetBundleForFile(entry.Path)
		results = append(results, &Folder{
			ID:       entry.ID,
			Path:     entry.Path,
			URI:      entry.URI,
			Name:     entry.Name,
			ParentID: parentID,
			BundleID: &bundleID,
		})
	}
	return results
}

// GetFiles MUST retrieve the requested value or return an error.
// GetFiles retrieves and returns the files.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️getfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/GetFiles)
func (c *repoContext) GetFiles() []*File {
	ctx := NewCodebaseContext()
	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err != nil {
		return []*File{}
	}
	files := BuildCodebaseFiles(ctx)
	results := make([]*File, 0, len(files))
	for _, entry := range files {
		bundleID := ctx.GetBundleForFile(entry.Path)
		folder := filepath.Dir(entry.Path)
		var folderID *string
		if folder != "." {
			fid := ctx.GetFolderID(folder)
			folderID = &fid
		}
		ext := strings.TrimPrefix(filepath.Ext(entry.Path), ".")
		results = append(results, &File{
			ID:        entry.ID,
			Path:      entry.Path,
			URI:       entry.URI,
			Name:      filepath.Base(entry.Path),
			Extension: ext,
			FolderID:  folderID,
			BundleID:  &bundleID,
		})
	}
	return results
}

// GetDefinitions MUST retrieve the requested value or return an error.
// GetDefinitions retrieves and returns the definitions.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️getdefinitions](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/GetDefinitions)
func (c *repoContext) GetDefinitions() []*Definition {
	ctx := NewCodebaseContext()
	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err != nil {
		return []*Definition{}
	}
	var results []*Definition
	for _, file := range ctx.Files {
		tool := ToolDefinitionList(file)
		definitions, ok := tool.Data.([]Definition)
		if !ok {
			continue
		}
		fileID := ctx.GetFileID(file)
		for i := range definitions {
			def := definitions[i]

			var sectionSegments []string
			if def.SectionPath != "" {
				sectionSegments = strings.Split(def.SectionPath, "/")
			}
			id := buildDefinitionID(fileID, sectionSegments, def.Name, def.Kind)
			results = append(results, &Definition{
				Name:        def.Name,
				Kind:        def.Kind,
				FilePath:    def.FilePath,
				SectionPath: def.SectionPath,
				StartLine:   def.StartLine,
				EndLine:     def.EndLine,
				ID:          id,
			})
		}
	}
	return results
}

// GetSections MUST retrieve the requested value or return an error.
// GetSections retrieves and returns the sections.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️getsections](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/GetSections)
func (c *repoContext) GetSections() []*Section {
	ctx := NewCodebaseContext()
	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err != nil {
		return []*Section{}
	}
	var results []*Section
	for _, file := range ctx.Files {
		tool := ToolSectionList(file)
		sections, ok := tool.Data.([]Section)
		if !ok {
			continue
		}
		fileID := ctx.GetFileID(file)
		for i := range sections {
			sec := sections[i]

			id := buildSectionID(fileID, strings.Split(sec.Path, "/"))
			results = append(results, &Section{
				Name:       sec.Name,
				Path:       sec.Path,
				FilePath:   sec.FilePath,
				StartLine:  sec.StartLine,
				EndLine:    sec.EndLine,
				StartIndex: sec.StartIndex,
				EndIndex:   sec.EndIndex,
				ID:         id,
			})
		}
	}
	return results
}

