// TicketClose MUST return a non-nil error when the operation fails.
// TicketClose performs the ticket close operation on the repo context.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️ticketclose](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/TicketClose)
func (c *repoContext) TicketClose(input TicketCloseInput) (*Ticket, error) {
	if input.All {
		tickets, err := ListTickets(nil, nil, nil)
		if err != nil {
			return nil, err
		}
		var lastTicket *Ticket
		for _, t := range tickets {
			if t.Status == TicketStatusOpen {
				ticket := t
				fmt.Printf("Closing ticket %s...\n", ticket.Slug)
				if err := FinishTicket(&ticket, "Bulk close", []string{}, input.NoManagement, true); err != nil {
					fmt.Printf("Warning: Failed to close ticket %s: %v\n", ticket.Slug, err)
					continue
				}
				lastTicket = &ticket
			}
		}

		if !input.NoManagement {
			issueURLs, err := c.managementProvider.ListOpenIssuesWithLabel("ticket")
			if err != nil {
				fmt.Printf("Warning: Failed to list GitHub issues with 'ticket' label: %v\n", err)
			} else {
				for _, issueURL := range issueURLs {
					fmt.Printf("Closing GitHub issue %s...\n", issueURL)
					if err := c.managementProvider.CloseIssue(issueURL); err != nil {
						fmt.Printf("Warning: Failed to close GitHub issue %s: %v\n", issueURL, err)
					}
				}
			}
		}
		return lastTicket, nil
	}
	ticket, err := ReadTicket(input.Year, input.Month, input.Day, input.Slug)
	if err != nil {
		return nil, err
	}

	if input.Title != nil && *input.Title != "" {
		if err := UpdateTicketTitle(ticket, *input.Title); err != nil {
			return nil, err
		}

		if ticket.Management != nil && ticket.Management.Issue != "" && !input.NoManagement {
			if err := c.managementProvider.UpdateIssueTitle(ticket.Management.Issue, *input.Title); err != nil {
				fmt.Printf("Warning: Failed to update GitHub issue title: %v\n", err)
			}
		}
	}
	if err := FinishTicket(ticket, input.Summary, input.Files, input.NoManagement, false); err != nil {
		return nil, err
	}
	return ticket, nil
}

// TicketReopen MUST return a non-nil error when the operation fails.
// TicketReopen performs the ticket reopen operation on the repo context.
// [🧰repo⌨️cli💻main🔖types🔖defaultcontext🛠️ticketreopen](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Default%20Context/d/i/TicketReopen)
