// Policies MUST return a non-nil error when the operation fails.
// Policies performs the policies operation on the query resolver.
// [🧰repo⌨️cli💻main🔖types🔖queryresolvers🛠️policies](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Query%20Resolvers/d/i/Policies)
func (r *queryResolver) Policies(ctx context.Context, filter *FilterInput) ([]*Policy, error) {
	if r.Ctx != nil {
		opts := filter.ToStreamOptions()
		policyChan := make(chan PolicyDef)
		go StreamPolicies(ctx, policyChan, opts)
		var policies []*Policy
		for p := range policyChan {
			desc := p.Description
			var vks []*StatuteMeta
			for _, k := range p.AllKinds() {
				meta := k.Info()
				meta.PolicyID = p.ID
				normalizeStatuteMeta(&meta)
				vks = append(vks, &meta)
			}
			policies = append(policies, &Policy{
				ID:          p.ID,
				Name:        p.Name,
				Description: &desc,
				Scopes:      p.Scopes,
				Groups:      p.Groups,
				Statutes:    vks,
			})
		}
		return policies, nil
	}
	return []*Policy{}, nil
}

