// AnalyzeFile performs the analyze file operation.
// [🧰repo⌨️cli💻main🔖types🔖cli🛠️analyzefile](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/AnalyzeFile)
func AnalyzeFile(filePath string, bundles []Bundle) ([]Breach, error) {
	scope := Scope{
		Kind:     ScopeFile,
		FilePath: filePath,
	}
	files := filterConsideredFiles([]string{filePath})
	files = filterGitIgnored(files)
	ctx := NewPolicyContextWithFiles(scope, bundles, files)
	return CheckPoliciesWithContext(ctx, nil)
}

// ParseContributorIdentity MUST return the parsed result or an error for invalid input.
// ParseContributorIdentity parses and returns the contributor identity from the input.
// [🧰repo⌨️cli💻main🔖types🔖cli🛠️parsecontributoridentity](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/ParseContributorIdentity)
func ParseContributorIdentity(line string) (name, email string, ok bool) {
	re := regexp.MustCompile(`\d{4}\s+(.+?)\s*<([^>]+)>`)
	m := re.FindStringSubmatch(line)
	if m == nil {
		return "", "", false
	}
	return strings.TrimSpace(m[1]), strings.TrimSpace(m[2]), true
}

// [🧰repo⌨️cli💻main🔖types🔖cli🛠️findsectionfordefinition](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/findSectionForDefinition)
// findSectionForDefinition MUST perform the findSectionForDefinition operation.
// findSectionForDefinition performs the findSectionForDefinition operation.
func findSectionForDefinition(sections []Section, startLine, endLine int, prefix string) string {
	for _, s := range sections {
		if startLine >= s.StartLine && endLine <= s.EndLine {
			p := s.Name
			if prefix != "" {
				p = prefix + "#" + s.Name
			}
			if len(s.Children) > 0 {
				if cp := findSectionForDefinition(s.Children, startLine, endLine, p); cp != "" {
					return cp
				}
			}
			return p
		}
	}
	return prefix
}

// ListContributors MUST return all available contributors entries.
// ListContributors returns a list of contributors entries.
// [🧰repo⌨️cli💻main🔖types🔖cli🛠️listcontributors](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/ListContributors)
func ListContributors() ([]Contributor, error) {
	var result []Contributor
	dir := filepath.Join(GetRepoMetaDir(), "🧑‍💻")
	if !FileExists(dir) {
		return []Contributor{{Alias: "unknown", Github: "unknown", Name: "Unknown"}}, nil
	}
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		p := filepath.Join(dir, e.Name(), "contributor.json")
		if !FileExists(p) {
			continue
		}
		content, _ := ReadTextFile(p)
		var c Contributor
		json.Unmarshal([]byte(content), &c)
		if c.Alias == "" {
			c.Alias = e.Name()
		}
		if c.Github == "" {
			c.Github = e.Name()
		}
		result = append(result, c)
	}
	return result, nil
}

// StreamContributors MUST invoke the callback for each matching contributors entry.
// StreamContributors streams contributors entries through the callback.
// [🧰repo⌨️cli💻main🔖types🔖cli🛠️streamcontributors](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/StreamContributors)
func StreamContributors(ctx context.Context, out chan<- Contributor, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	contributors, err := ListContributors()
	if err != nil {
		return err
	}

	for _, c := range contributors {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			if !matchesFilter(c.Alias, options) && !matchesFilter(c.Name, options) {
				continue
			}
			queryTextParts := []string{c.Alias, c.Name, c.Github, c.Email}
			queryTextParts = append(queryTextParts, c.Aliases...)
			queryTextParts = append(queryTextParts, c.Githubs...)
			queryTextParts = append(queryTextParts, c.Names...)
			queryTextParts = append(queryTextParts, c.Emails...)
			if !matchesQuery(strings.Join(queryTextParts, " "), options) {
				continue
			}
			if len(options.IncludeContributors) > 0 {
				found := false
				for _, id := range options.IncludeContributors {
					if c.Alias == id || c.Name == id {
						found = true
						break
					}
				}
				if !found {
					continue
				}
			}
			if len(options.ExcludeContributors) > 0 {
				excluded := false
				for _, id := range options.ExcludeContributors {
					if c.Alias == id || c.Name == id {
						excluded = true
						break
					}
				}
				if excluded {
					continue
				}
			}
			out <- c
		}
	}
	return nil
}

