// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure)
// Configure command auto-generates native hook configs for all supported clients.

// ClientHookMapping maps client names to their native event configuration format.
// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure✂️clienthookmapping](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure/d/i/ClientHookMapping)
type ClientHookMapping struct {
	Client     string
	ConfigPath string
	Generator  func(repoRoot string) (string, error)
}

// configureCommand creates the `configure` cobra command.
// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure🛠️configurecommand](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure/d/i/configureCommand)
// configureCommand MUST perform the configureCommand operation.
func configureCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "configure",
		Short: "Auto-configure repo hooks for all supported clients",
		RunE: func(cmd *cobra.Command, args []string) error {
			repoRoot := config.Repo
			if repoRoot == "" {
				cwd, _ := os.Getwd()
				repoRoot = findRepoRoot(cwd)
			}
			var errs []error
			for _, provider := range AllEditorProviders() {
				mapping := provider.HookMapping()
				if mapping.ConfigPath == "" {
					continue
				}
				if err := provider.Configure(repoRoot); err != nil {
					errs = append(errs, fmt.Errorf("%s: %w", provider.Kind(), err))
					continue
				}
				fmt.Printf("✓ %s → %s\n", provider.Kind(), mapping.ConfigPath)
			}
			if err := configureGitHooks(repoRoot); err != nil {
				errs = append(errs, fmt.Errorf("git hooks: %w", err))
			} else {
				fmt.Println("✓ git hooks configured")
			}
			if len(errs) > 0 {
				for _, e := range errs {
					fmt.Fprintf(os.Stderr, "✗ %v\n", e)
				}
				return fmt.Errorf("%d configuration(s) failed", len(errs))
			}
			return nil
		},
	}
	return cmd
}

// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure🛠️configuregithooks](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure/d/i/configureGitHooks)
// configureGitHooks holds the data fields for a configureGitHooks record.
// configureGitHooks MUST perform the configureGitHooks operation.
func configureGitHooks(repoRoot string) error {
	hooksDir := filepath.Join(repoRoot, ".git", "hooks")
	if err := unsetLocalCoreHooksPath(repoRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(hooksDir, 0755); err != nil {
		return err
	}
	preCommitPath := filepath.Join(hooksDir, "pre-commit")
	preCommitScript := `#!/usr/bin/env sh
set -eu
repo_root="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$repo_root" ] || [ ! -f "$repo_root/.pre-commit-config.yaml" ]; then
  exit 0
fi
cd "$repo_root"
if command -v uv >/dev/null 2>&1; then
  uv run --group dev pre-commit run --hook-stage pre-commit
  exit $?
fi
if command -v pre-commit >/dev/null 2>&1; then
  pre-commit run --hook-stage pre-commit
  exit $?
fi
echo "pre-commit is required. install with: uv sync --group dev" >&2
exit 1
`
	if err := os.WriteFile(preCommitPath, []byte(preCommitScript), 0755); err != nil {
		return err
	}
	postCheckpointPath := filepath.Join(hooksDir, "post-commit")
	postCheckpointScript := `#!/usr/bin/env sh
set -eu
repo_root="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$repo_root" ] || [ ! -f "$repo_root/repo/cli/cli" ]; then
  exit 0
fi
cd "$repo_root"
./repo/cli/cli hook version.checkpoint.ended
`
	if err := os.WriteFile(postCheckpointPath, []byte(postCheckpointScript), 0755); err != nil {
		return err
	}
	return nil
}

// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure🛠️unsetlocalcorehookspath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure/d/i/unsetLocalCoreHooksPath)
// unsetLocalCoreHooksPath holds the data fields for a unsetLocalCoreHooksPath record.
// unsetLocalCoreHooksPath MUST perform the unsetLocalCoreHooksPath operation.
func unsetLocalCoreHooksPath(repoRoot string) error {
	cmd := exec.Command("git", "-C", repoRoot, "config", "--local", "--get", "core.hooksPath")
	out, err := cmd.Output()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok && exitErr.ExitCode() == 1 {
			return nil
		}
		return err
	}
	if strings.TrimSpace(string(out)) == "" {
		return nil
	}
	unsetCmd := exec.Command("git", "-C", repoRoot, "config", "--local", "--unset-all", "core.hooksPath")
	if unsetErr := unsetCmd.Run(); unsetErr != nil {
		return unsetErr
	}
	return nil
}

// getClientHookMappings MUST perform the getClientHookMappings operation.
// [🧰repo⌨️cli💻main🔖types🔖cli🔖configure🪨getclienthookmappings](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Configure/d/i/getClientHookMappings)
// getClientHookMappings performs the getClientHookMappings operation.
func getClientHookMappings() []ClientHookMapping {
	var mappings []ClientHookMapping
	for _, provider := range AllEditorProviders() {
		m := provider.HookMapping()
		if m.ConfigPath == "" {
			continue
		}
		gen := provider.GenerateHookConfig
		mappings = append(mappings, ClientHookMapping{Client: m.Client, ConfigPath: m.ConfigPath, Generator: gen})
	}
	return mappings
}

