// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️extractfileandsectionsfromuri](repo://definition/🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️extractfileandsectionsfromuri)
// extractFileAndSectionsFromUri extracts the file path and section names from a URI.
// Supports new format repo://section/{{id}} where ID encodes file+sections as emojis.
func extractFileAndSectionsFromUri(uri string) (filePath string, sectionSlugs []string) {
	// New format: repo://section/{{id}}
	if strings.HasPrefix(uri, "repo://section/") || strings.HasPrefix(uri, "repo://file/") {
		id := UriToId(uri)
		if id == "" {
			return "", nil
		}
		filePath = IdToPath(id)
		sectionSlugs = IdToSectionPath(id)
		return filePath, sectionSlugs
	}
	// Try the raw string as an ID (for cases where "repo://" was already stripped)
	prefixStripped := strings.TrimPrefix(uri, "repo://")
	if strings.HasPrefix(prefixStripped, "section/") || strings.HasPrefix(prefixStripped, "file/") {
		fullUri := "repo://" + prefixStripped
		id := UriToId(fullUri)
		if id != "" {
			return IdToPath(id), IdToSectionPath(id)
		}
	}
	// Legacy fallback: parse old /f/ and /s/ format
	p := prefixStripped
	var sectionParts []string
	remaining := p
	for {
		idx := strings.Index(remaining, "/s/")
		if idx < 0 {
			break
		}
		after := remaining[idx+3:]
		nextS := strings.Index(after, "/s/")
		nextD := strings.Index(after, "/d/")
		endIdx := len(after)
		if nextS >= 0 && nextS < endIdx {
			endIdx = nextS
		}
		if nextD >= 0 && nextD < endIdx {
			endIdx = nextD
		}
		sectionParts = append(sectionParts, PathFromUriPath(after[:endIdx]))
		remaining = after[endIdx:]
	}
	fIdx := strings.Index(p, "/f/")
	if fIdx >= 0 {
		rest := p[fIdx+3:]
		nextSlash := strings.Index(rest, "/")
		if nextSlash < 0 {
			filePath = PathFromUriPath(rest)
		} else {
			filePath = PathFromUriPath(rest[:nextSlash])
		}
	}
	return filePath, sectionParts
}

// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️extractfileanddefinitionfromuri](repo://definition/🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️extractfileanddefinitionfromuri)
// extractFileAndDefinitionFromUri extracts the file path and definition name from a URI.
// Supports new format repo://definition/{{id}} where ID encodes file+sections+definition as emojis.
func extractFileAndDefinitionFromUri(uri string) (filePath string, defName string) {
	// New format: repo://definition/{{id}}
	if strings.HasPrefix(uri, "repo://definition/") {
		id := UriToId(uri)
		if id == "" {
			return "", ""
		}
		filePath = IdToPath(id)
		defName = IdToDefinitionName(id)
		return filePath, defName
	}
	// Try with the raw string (for cases where "repo://" was already stripped)
	prefixStripped := strings.TrimPrefix(uri, "repo://")
	if strings.HasPrefix(prefixStripped, "definition/") {
		fullUri := "repo://" + prefixStripped
		id := UriToId(fullUri)
		if id != "" {
			return IdToPath(id), IdToDefinitionName(id)
		}
	}
	// Legacy fallback: parse old /f/ and /d/ format
	p := prefixStripped
	fIdx := strings.Index(p, "/f/")
	if fIdx >= 0 {
		rest := p[fIdx+3:]
		nextSlash := strings.Index(rest, "/")
		if nextSlash < 0 {
			filePath = PathFromUriPath(rest)
		} else {
			filePath = PathFromUriPath(rest[:nextSlash])
		}
	}
	dIdx := strings.LastIndex(p, "/d/")
	if dIdx >= 0 {
		rest := p[dIdx+3:]
		dParts := strings.SplitN(rest, "/", 2)
		if len(dParts) >= 2 {
			defName = PathFromUriPath(dParts[1])
		}
	}
	return filePath, defName
}

// ArtifactRef holds the data fields for a artifact ref record.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid✂️artifactref](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ArtifactRef)
type ArtifactRef struct {
	Kind         string
	Path         string
	SectionParts []string
}

// ParseArtifactRef MUST return the parsed result or an error for invalid input.
// ParseArtifactRef parses and returns the artifact ref from the input.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️parseartifactref](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ParseArtifactRef)
func ParseArtifactRef(ref string) ArtifactRef {
	clean := strings.ReplaceAll(ref, "\uFE0E", "")
	clean = strings.ReplaceAll(clean, "\uFE0F", "")
	if uri := IdToUri(clean); uri != "" && strings.HasPrefix(uri, "repo://") {
		if containsUriSection(uri) && !containsUriDefinition(uri) {
			filePath, sectionSlugs := extractFileAndSectionsFromUri(uri)
			return ArtifactRef{Kind: "section", Path: NormalizePath(filePath), SectionParts: sectionSlugs}
		}
		if containsUriDefinition(uri) {
			filePath, defName := extractFileAndDefinitionFromUri(uri)
			if defName != "" {
				return ArtifactRef{Kind: "definition", Path: NormalizePath(filePath + "§" + defName)}
			}
			return ArtifactRef{Kind: "definition", Path: NormalizePath(filePath)}
		}
	}

	sectionEmojis := []string{"🔖"}
	for _, e := range sectionEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			parts := strings.SplitN(rest, "#", 2)
			filePath := NormalizePath(parts[0])
			var sectionParts []string
			if len(parts) > 1 {
				sectionParts = strings.Split(parts[1], "#")
			}
			return ArtifactRef{Kind: "section", Path: filePath, SectionParts: sectionParts}
		}
	}

	defEmojis := []string{"🏷️", "✂️️", "🪨", "🛠️"}
	for _, e := range defEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "definition", Path: NormalizePath(rest)}
		}
	}

	folderEmojis := []string{"📁", "🗃️", "📂"}
	for _, e := range folderEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "folder", Path: NormalizePath(strings.TrimSuffix(rest, "/"))}
		}
	}

	fileEmojis := []string{"💻", "🥼", "📜", "📃", "⚙️", "💾", "⚖️", "📄"}
	for _, e := range fileEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "file", Path: NormalizePath(rest)}
		}
	}

	if strings.Contains(ref, "#") {
		parts := strings.SplitN(ref, "#", 2)
		filePath := NormalizePath(parts[0])
		var sectionParts []string
		if len(parts) > 1 {
			sectionParts = strings.Split(parts[1], "#")
		}
		return ArtifactRef{Kind: "section", Path: filePath, SectionParts: sectionParts}
	}
	if strings.HasSuffix(ref, "/") {
		return ArtifactRef{Kind: "folder", Path: NormalizePath(strings.TrimSuffix(ref, "/"))}
	}
	normalized := NormalizePath(ref)
	absPath := filepath.Join(rootDir, normalized)
	if info, err := os.Stat(absPath); err == nil && info.IsDir() {
		return ArtifactRef{Kind: "folder", Path: normalized}
	}
	return ArtifactRef{Kind: "file", Path: normalized}
}

// UnSlugify MUST complete the operation successfully.
// UnSlugify performs the un slugify operation.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️unslugify](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/UnSlugify)
func UnSlugify(slug string) string {
	parts := strings.Split(slug, "-")
	for i, p := range parts {
		if len(p) > 0 {
			parts[i] = strings.ToUpper(p[:1]) + strings.ToLower(p[1:])
		}
	}
	return strings.Join(parts, " ")
}

// FindSectionBySlug MUST return the matching result or an error if not found.
// FindSectionBySlug locates and returns the matching section by slug.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️findsectionbyslug](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/FindSectionBySlug)
func FindSectionBySlug(sections []Section, slug string) *Section {
	for i := range sections {
		if Slugify(sections[i].Name) == slug {
			return &sections[i]
		}
		if found := FindSectionBySlug(sections[i].Children, slug); found != nil {
			return found
		}
	}
	return nil
}

// ResolveSectionName MUST return the resolved value or an error if unresolvable.
// ResolveSectionName resolves and returns the section name.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️resolvesectionname](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ResolveSectionName)
func ResolveSectionName(filePath string, slug string) string {
	absPath := filepath.Join(rootDir, filePath)
	content, err := ReadTextFile(absPath)
	if err != nil {
		return UnSlugify(slug)
	}
	lang := GetLanguage(filePath)
	if lang == nil || !lang.SupportsSections() {
		return UnSlugify(slug)
	}
	sections := lang.ParseSections(content)
	section := FindSectionBySlug(sections, slug)
	if section != nil {
		return section.Name
	}
	return UnSlugify(slug)
}

// SectionIdValueToUriPath MUST complete the operation successfully.
// SectionIdValueToUriPath performs the section id value to uri path operation.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️sectionidvaluetouripath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/SectionIdValueToUriPath)
func SectionIdValueToUriPath(value string) string {
	hashIdx := strings.Index(value, "#")
	if hashIdx < 0 {
		return PathToUriPath(value)
	}
	filePath := value[:hashIdx]
	rest := value[hashIdx+1:]
	sectionParts := strings.Split(rest, "#")
	result := PathToUriPath(filePath)
	for _, p := range sectionParts {
		result += "/" + PathToUriPath(p)
	}
	return result
}

// DefinitionIdValueToUriPath MUST complete the operation successfully.
// DefinitionIdValueToUriPath performs the definition id value to uri path operation.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️definitionidvaluetouripath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/DefinitionIdValueToUriPath)
func DefinitionIdValueToUriPath(value string) string {
	hashIdx := strings.Index(value, "#")
	paragraphIdx := strings.Index(value, "§")
	if hashIdx < 0 && paragraphIdx < 0 {
		return PathToUriPath(value)
	}
	if hashIdx < 0 && paragraphIdx >= 0 {
		filePath := value[:paragraphIdx]
		defName := value[paragraphIdx+len("§"):]
		return PathToUriPath(filePath) + "/" + PathToUriPath(defName)
	}
	filePath := value[:hashIdx]
	rest := value[hashIdx+1:]
	parts := strings.Split(rest, "§")
	result := PathToUriPath(filePath)
	for _, p := range parts {
		subParts := strings.Split(p, "#")
		for _, sp := range subParts {
			result += "/" + PathToUriPath(sp)
		}
	}
	return result
}

// ParseSectionUriPath MUST return the parsed result or an error for invalid input.
// ParseSectionUriPath parses and returns the section uri path from the input.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️parsesectionuripath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ParseSectionUriPath)
func ParseSectionUriPath(uriPath string) (filePath string, sectionSlugs []string) {
	parts := strings.Split(uriPath, "/")
	fileEnd := -1
	for i, p := range parts {
		if strings.Contains(p, ".") {
			fileEnd = i
		}
	}
	if fileEnd < 0 {
		return uriPath, nil
	}
	filePath = strings.Join(parts[:fileEnd+1], "/")
	if fileEnd+1 < len(parts) {
		sectionSlugs = parts[fileEnd+1:]
	}
	return
}

// StatuteIdToUriPath MUST complete the operation successfully.
// StatuteIdToUriPath performs the statute id to uri path operation.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️statuteidtouripath](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/StatuteIdToUriPath)
func StatuteIdToUriPath(id string) string {
	parts := strings.Split(id, "/")
	for i, p := range parts {
		parts[i] = PathToUriPath(p)
	}
	return strings.Join(parts, "/")
}

// StatuteUriPathToId MUST complete the operation successfully.
// StatuteUriPathToId performs the statute uri path to id operation.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️statuteuripathtoid](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/StatuteUriPathToId)
func StatuteUriPathToId(uriPath string) string {
	parts := strings.Split(uriPath, "/")
	for i, p := range parts {
		parts[i] = PathFromUriPath(p)
	}
	return strings.Join(parts, "/")
}

// GetArtifactID MUST retrieve the requested value or return an error.
// GetArtifactID retrieves and returns the artifact i d.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️getartifactid](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/GetArtifactID)
func GetArtifactID(kind string, data map[string]interface{}) string {
	parentId, _ := data["parentId"].(string)
	switch kind {
	case "root":
		return ""
	case "years":
		return parentId + emojiText(EmojiYears)
	case "year":
		yy, _ := data["yy"].(string)
		return parentId + emojiText(EmojiYear) + yy
	case "months":
		return parentId + emojiText(EmojiMonths)
	case "month":
		mm, _ := data["mm"].(string)
		return parentId + emojiText(EmojiMonth) + mm
	case "days":
		return parentId + emojiText(EmojiDays)
	case "day":
		dd, _ := data["dd"].(string)
		return parentId + emojiText(EmojiDay) + dd
	case "hours":
		return parentId + emojiText(EmojiHours)
	case "hour":
		hh, _ := data["hh"].(string)
		return parentId + emojiText(EmojiHour) + hh
	case "minutes":
		return parentId + emojiText(EmojiMinutes)
	case "minute":
		mm, _ := data["mm"].(string)
		return parentId + emojiText(EmojiMinute) + mm
	case "seconds":
		return parentId + emojiText(EmojiSeconds)
	case "second":
		ss, _ := data["ss"].(string)
		return parentId + emojiText(EmojiSecond) + ss
	case "codebase":
		return parentId + emojiText(EmojiCodebase)
	case "technologies":
		return parentId + emojiText(EmojiTechnologies)
	case "technology":
		name, _ := data["name"].(string)
		return technologyKindEmoji(data) + Flat(name)
	case "bundles":
		return parentId + emojiText(EmojiBundles)
	case "bundle":
		name, _ := data["name"].(string)
		parts := strings.SplitN(name, "/", 2)
		technologyCode := parts[0]
		bundleCode := technologyCode
		if len(parts) > 1 {
			bundleCode = parts[1]
		}
		pKind := DeriveTechnologyKind(technologyCode)
		return emojiText(string(pKind)) + Flat(technologyCode) + bundleKindEmoji(data) + Flat(bundleCode)
	case "folders":
		return parentId + emojiText(EmojiFolders)
	case "folder":
		path, _ := data["path"].(string)
		name := filepath.Base(path)
		return parentId + folderKindEmoji(data) + Flat(name)
	case "files":
		return parentId + emojiText(EmojiFiles)
	case "file":
		path, _ := data["path"].(string)
		if path == "" {
			path, _ = data["id"].(string)
		}
		name := filepath.Base(path)
		ext := filepath.Ext(name)
		if ext != "" {
			name = strings.TrimSuffix(name, ext)
		}
		return parentId + fileKindEmoji(data) + Flat(name)
	case "sections":
		return parentId + emojiText(EmojiSections)
	case "section":
		path, _ := data["path"].(string)
		if path == "" {
			filePath, _ := data["filePath"].(string)
			name, _ := data["name"].(string)
			if filePath != "" && name != "" {
				path = filePath + "#" + name
			} else if name != "" {
				path = name
			}
		}
		if parentId != "" {
			hashIdx := strings.LastIndex(path, "#")
			sectionName := path
			if hashIdx >= 0 {
				sectionName = path[hashIdx+1:]
			}
			return parentId + emojiText(EmojiSection) + Flat(sectionName)
		}
		hashIdx := strings.Index(path, "#")
		if hashIdx >= 0 {
			filePath := NormalizePath(path[:hashIdx])
			sectionPart := path[hashIdx+1:]
			sectionPath := strings.Split(sectionPart, "#")
			fileId := buildFileID(filePath, nil)
			return buildSectionID(fileId, sectionPath)
		}
		name, _ := data["name"].(string)
		if name != "" {
			return emojiText(EmojiSection) + Flat(name)
		}
		return emojiText(EmojiSection) + Flat(path)
	case "definitions":
		return parentId + emojiText(EmojiDefinitions)
	case "definition":
		k := definitionKindEmoji(data)
		name, _ := data["name"].(string)
		if name == "" {
			id, _ := data["id"].(string)
			if id != "" {
				paragraphIdx := strings.LastIndex(id, "§")
				if paragraphIdx >= 0 {
					name = id[paragraphIdx+len("§"):]
				} else {
					hashIdx := strings.LastIndex(id, "#")
					if hashIdx >= 0 {
						name = id[hashIdx+1:]
					} else {
						name = id
					}
				}
			}
		}
		if parentId != "" {
			return parentId + k + Flat(name)
		}
		sectionPath, _ := data["sectionPath"].(string)
		filePath, _ := data["filePath"].(string)
		if filePath == "" {
			id, _ := data["id"].(string)
			if id != "" {
				if paragraphIdx := strings.LastIndex(id, "§"); paragraphIdx >= 0 {
					name = id[paragraphIdx+len("§"):]
					if hashIdx := strings.Index(id[:paragraphIdx], "#"); hashIdx >= 0 {
						filePath = id[:hashIdx]
						sectionPath = strings.ReplaceAll(id[hashIdx+1:paragraphIdx], "#", "/")
					} else {
						filePath = id[:paragraphIdx]
					}
				} else if hashIdx := strings.LastIndex(id, "#"); hashIdx >= 0 {
					name = id[hashIdx+1:]
					filePath = id[:hashIdx]
				}
			}
		}
		if filePath != "" {
			fileId := buildFileID(filePath, nil)
			sectionId := fileId
			if sectionPath != "" {
				sections := strings.Split(strings.ReplaceAll(sectionPath, "#", "/"), "/")
				sectionId = buildSectionID(fileId, sections)
			}
			return sectionId + k + Flat(name)
		}
		return k + Flat(name)
	case "tickets":
		return parentId + emojiText(EmojiTickets)
	case "ticket":
		if parentId == "" {
			if goalId, ok := data["goalId"].(string); ok && goalId != "" {
				parentId = goalArtifactID(goalId)
			}
		}
		slug, _ := data["slug"].(string)
		title, _ := data["title"].(string)
		if slug == "" && title != "" {
			slug = title
		}
		if slug == "" {
			if id, ok := data["id"].(string); ok && id != "" {
				return id
			}
		}
		return parentId + emojiText(EmojiTicket) + Flat(slug)
	case "goals":
		return parentId + emojiText(EmojiGoals)
	case "goal":
		id, _ := data["id"].(string)
		name := id
		if idx := strings.LastIndex(id, "/"); idx >= 0 {
			name = id[idx+1:]
		}
		return parentId + emojiText(EmojiGoal) + Flat(name)
	case "drafts":
		return parentId + emojiText(EmojiDrafts)
	case "draft":
		slug, _ := data["slug"].(string)
		if slug == "" {
			slug, _ = data["id"].(string)
		}
		return parentId + emojiText(EmojiDraft) + Flat(slug)
	case "todos":
		return parentId + emojiText(EmojiTodos)
	case "todo":
		slug, _ := data["id"].(string)
		return parentId + emojiText(EmojiTodo) + Flat(slug)
	case "policies":
		return parentId + emojiText(EmojiPolicies)
	case "policy":
		slug, _ := data["id"].(string)
		slug = strings.TrimPrefix(slug, "/")
		return parentId + emojiText(EmojiPolicy) + Flat(slug)
	case "statutes":
		return ""
	case "statute":
		id, _ := data["id"].(string)
		return Flat(id)
	case "contributors":
		return parentId + emojiText(EmojiContributors)
	case "contributor":
		alias, _ := data["alias"].(string)
		if alias == "" {
			alias, _ = data["github"].(string)
		}
		return emojiText(EmojiContributor) + Flat(alias)
	case "checkpoints":
		return parentId + emojiText(EmojiCheckpoints)
	case "checkpoint":
		sha, _ := data["sha"].(string)
		contributorId, _ := data["contributorId"].(string)
		if contributorId == "" {
			if authorId, ok := data["authorId"].(string); ok && authorId != "" {
				contributorId = emojiText(EmojiContributor) + Flat(authorId)
			}
		}
		return contributorId + emojiText(EmojiCheckpoint) + sha
	case "line":
		lineNum, _ := data["line"].(float64)
		return parentId + emojiText(EmojiLine) + fmt.Sprintf("%d", int(lineNum))
	case "range":
		startLine, _ := data["startLine"].(float64)
		endLine, _ := data["endLine"].(float64)
		return parentId + emojiText(EmojiLine) + fmt.Sprintf("%d", int(startLine)) + emojiText(EmojiLine) + fmt.Sprintf("%d", int(endLine))
	case "breach":
		policyId := parentId
		affected, _ := data["affected"].(string)
		lineId, _ := data["lineId"].(string)
		secondId, _ := data["secondId"].(string)
		return policyId + emojiText(EmojiBreach) + affected + emojiText(EmojiBreachScope) + lineId + secondId
	case "breaches":
		return parentId + emojiText(EmojiBreaches)
	case "interactions":
		return parentId + emojiText(EmojiInteractions)
	case "interaction":
		k := interactionKindEmoji(data)
		secondId, _ := data["secondId"].(string)
		contributorId, _ := data["contributorId"].(string)
		entityID, _ := data["entityId"].(string)
		return secondId + contributorId + entityID + k
	case "sessions":
		return parentId + emojiText(EmojiSessions)
	case "session":
		uuid, _ := data["uuid"].(string)
		if uuid == "" {
			uuid, _ = data["id"].(string)
		}
		return parentId + emojiText(EmojiSession) + Flat(uuid)
	}
	return ""
}

// GetArtifactURI MUST retrieve the requested value or return an error.
// GetArtifactURI retrieves and returns the artifact URI using the format repo://{{entity-kind}}/{{id}}.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️getartifacturi](repo://definition/🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖artifactid🛠️getartifacturi)
func GetArtifactURI(kind string, data map[string]interface{}) string {
	id := GetArtifactID(kind, data)
	if id == "" {
		return "repo://" + kind
	}
	return "repo://" + kind + "/" + id
}

