func extractFinishedStr(data map[string]interface{}) string {
	finishedStr := ""
	if dates, ok := data["dates"].(map[string]interface{}); ok {
		finishedStr, _ = dates["finished"].(string)
	}
	if finishedStr == "" {
		if dates, ok := data["date"].(map[string]interface{}); ok {
			finishedStr, _ = dates["finished"].(string)
		}
	}
	if finishedStr == "" {
		finishedStr, _ = data["finishedAt"].(string)
	}
	if finishedStr == "" {
		if finished, ok := data["finished"].(string); ok {
			finishedStr = finished
		}
	}
	return finishedStr
}

// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖entityrendering🛠️sanitizeprop](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Entity%20Rendering/d/i/sanitizeProp)
// sanitizeProp MUST perform the sanitizeProp operation.
// sanitizeProp performs the sanitizeProp operation.
func sanitizeProp(v string) string {
	v = strings.ReplaceAll(v, "\r\n", " ")
	v = strings.ReplaceAll(v, "\n", " ")
	v = strings.ReplaceAll(v, "\r", " ")
	v = strings.ReplaceAll(v, "`", "'")
	for strings.Contains(v, "  ") {
		v = strings.ReplaceAll(v, "  ", " ")
	}
	return strings.TrimSpace(v)
}

// sanitizeSingleLine holds the data fields for a sanitizeSingleLine record.
// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖entityrendering🛠️sanitizesingleline](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Entity%20Rendering/d/i/sanitizeSingleLine)
// sanitizeSingleLine MUST perform the sanitizeSingleLine operation.
func sanitizeSingleLine(v string) string {
	v = strings.ReplaceAll(v, "\r\n", " ")
	v = strings.ReplaceAll(v, "\n", " ")
	v = strings.ReplaceAll(v, "\r", " ")
	return v
}

// [🧰repo⌨️cli💻main🔖types🔖todos🔖entityrendering🔖entityrendering🛠️collectentityprops](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Entity%20Rendering/d/i/collectEntityProps)
// collectEntityProps holds the data fields for a collectEntityProps record.
// collectEntityProps MUST perform the collectEntityProps operation.
func collectEntityProps(kind string, data map[string]interface{}, truncateDesc bool) []string {
	var props []string
	appendNonEmpty := func(vals ...string) {
		for _, v := range vals {
			if v != "" {
				v = sanitizeProp(v)
				if v != "" {
					props = append(props, v)
				}
			}
		}
	}
	switch kind {
	case "goal":
		title, _ := data["title"].(string)
		status, _ := data["status"].(string)
		createdStr := extractCreatedStr(data)
		createdDisplay := ""
		if createdStr != "" {
			if tParsed, err := parseFlexibleTime(createdStr); err == nil {
				createdDisplay = "created " + humanize.Time(tParsed)
			} else {
				createdDisplay = "created " + createdStr
			}
		}
		dueDate, _ := data["dueDate"].(string)
		if dueDate == "" {
			if dates, ok := data["dates"].(map[string]interface{}); ok {
				dueDate, _ = dates["due"].(string)
			}
		}
		dueDisplay := ""
		if dueDate != "" {
			if tParsed, err := parseFlexibleTime(dueDate); err == nil {
				dueDisplay = humanize.Time(tParsed)
			} else {
				dueDisplay = dueDate
			}
		}
		description, _ := data["description"].(string)
		if truncateDesc && len(description) > 80 {
			description = description[:80] + "..."
		}
		appendNonEmpty(title, status, createdDisplay, dueDisplay, description)
	case "ticket":
		title, _ := data["title"].(string)
		status, _ := data["status"].(string)
		createdStr := extractCreatedStr(data)
		finishedStr := extractFinishedStr(data)
		dateDisplay := ""
		if status == "open" || status == "OPEN" {
			if createdStr != "" {
				if tParsed, err := parseFlexibleTime(createdStr); err == nil {
					dateDisplay = "opened " + humanize.Time(tParsed)
				} else {
					dateDisplay = "opened " + createdStr
				}
			}
		} else {
			if finishedStr != "" {
				if tParsed, err := parseFlexibleTime(finishedStr); err == nil {
					dateDisplay = "closed " + humanize.Time(tParsed)
				} else {
					dateDisplay = "closed " + finishedStr
				}
			} else if createdStr != "" {
				if tParsed, err := parseFlexibleTime(createdStr); err == nil {
					dateDisplay = humanize.Time(tParsed)
				}
			}
		}
		prompt, _ := data["prompt"].(string)
		summary, _ := data["summary"].(string)
		content := ""
		if status == "open" || status == "OPEN" {
			content = prompt
		} else {
			content = summary
		}
		if truncateDesc && len(content) > 80 {
			content = content[:80] + "..."
		}
		appendNonEmpty(title, status, dateDisplay, content)
	case "bundle":
		root, _ := data["root"].(string)
		ptype, _ := data["projectType"].(string)
		if ptype == "" {
			ptype, _ = data["type"].(string)
		}
		appendNonEmpty(root, ptype)
	case "folder":
	case "file":
	case "section":
		start, _ := data["startLine"].(float64)
		end, _ := data["endLine"].(float64)
		if start > 0 || end > 0 {
			appendNonEmpty(fmt.Sprintf(":%d-%d", int(start), int(end)))
		}
	case "definition":
		name, _ := data["name"].(string)
		start, _ := data["startLine"].(float64)
		end, _ := data["endLine"].(float64)
		appendNonEmpty(name)
		if start > 0 || end > 0 {
			appendNonEmpty(fmt.Sprintf(":%d-%d", int(start), int(end)))
		}
	case "contributor":
		name, _ := data["name"].(string)
		appendNonEmpty(name)
	case "todo":
		name, _ := data["name"].(string)
		appendNonEmpty(name)
	case "draft":
	case "policy":
		desc, _ := data["description"].(string)
		appendNonEmpty(desc)
	case "statute":
		desc, _ := data["description"].(string)
		appendNonEmpty(desc)
	case "technology":
		desc, _ := data["description"].(string)
		appendNonEmpty(desc)
	case "checkpoint":
		msg, _ := data["message"].(string)
		appendNonEmpty(msg)
	case "root":
		name, _ := data["name"].(string)
		appendNonEmpty(name)
	}
	return props
}

