// resolvePytestFiles resolves test files for pytest commands.
// [🧰repo⌨️cli💻main🔖types🔖cli🔖hooks🛠️resolvepytestfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/resolvePytestFiles)
// resolvePytestFiles MUST perform the resolvePytestFiles operation.
func resolvePytestFiles(args []string, cwd string) []string {
	var files []string
	seen := map[string]bool{}
	addFile := func(path string) {
		if !seen[path] {
			seen[path] = true
			files = append(files, path)
		}
	}
	isPytestFile := func(path string) bool {
		base := filepath.Base(path)
		return strings.HasPrefix(base, "test_") || strings.Contains(base, "_test.") || strings.EqualFold(base, "conftest.py")
	}
	scanDir := func(root string) {
		_ = filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			if !info.IsDir() && strings.HasSuffix(path, ".py") && isPytestFile(path) {
				addFile(path)
			}
			return nil
		})
	}
	targets := make([]string, 0)
	for i := 0; i < len(args); i++ {
		arg := strings.TrimSpace(args[i])
		if arg == "" {
			continue
		}
		if strings.HasPrefix(arg, "-") {
			if (arg == "-k" || arg == "-m" || arg == "--maxfail" || arg == "-c") && i+1 < len(args) {
				i++
			}
			continue
		}
		targets = append(targets, arg)
	}
	if len(targets) == 0 {
		scanDir(cwd)
		return files
	}
	for _, target := range targets {
		targetPath := target
		if !filepath.IsAbs(targetPath) {
			targetPath = filepath.Join(cwd, targetPath)
		}
		info, err := os.Stat(targetPath)
		if err != nil {
			continue
		}
		if info.IsDir() {
			scanDir(targetPath)
			continue
		}
		if strings.HasSuffix(targetPath, ".py") && isPytestFile(targetPath) {
			addFile(targetPath)
		}
	}
	return files
}

// findJSTestFiles resolves test files for JavaScript test runners.
// [🧰repo⌨️cli💻main🔖types🔖cli🔖hooks🛠️findjstestfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/findJSTestFiles)
// findJSTestFiles MUST perform the findJSTestFiles operation.
func findJSTestFiles(cwd string) []string {
	var files []string
	// Look for test files with common patterns
	_ = filepath.Walk(cwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if !info.IsDir() && (strings.HasSuffix(path, ".js") || strings.HasSuffix(path, ".ts") || strings.HasSuffix(path, ".jsx") || strings.HasSuffix(path, ".tsx")) {
			base := filepath.Base(path)
			if strings.HasPrefix(base, "test.") || strings.HasSuffix(base, ".test.js") ||
				strings.HasSuffix(base, ".test.ts") || strings.HasSuffix(base, ".spec.js") ||
				strings.HasSuffix(base, ".spec.ts") {
				files = append(files, path)
			}
		}
		return nil
	})
	return files
}

